(window.JCPA_DATA=window.JCPA_DATA||{})["aqaba"]={"id":"aqaba","name":"قانون منطقة العقبة الاقتصادية الخاصة","full":"قانون منطقة العقبة الاقتصادية الخاصة رقم (32) لسنة 2000","icon":"⚓","articles":[{"n":"1","chapter":"","notes":[],"source":"يسمى هذا القانون (قانون منطقة العقبة الاقتصادية الخاصة لسنة 2000) ويعمل به من تاريخ نشره في الجريدة الرسمية.","title":"اسم القانون وبدء العمل به","memo":"⭐ قانون منطقة العقبة الاقتصادية الخاصة لسنة 2000\n⭐ يعمل به من تاريخ نشره في الجريدة الرسمية","qs":[{"q":"يعمل بقانون منطقة العقبة الاقتصادية الخاصة اعتباراً من:","o":["تاريخ نشره في الجريدة الرسمية","تاريخ إقراره من مجلس الأمة","مرور ثلاثين يوماً على نشره","التاريخ الذي يحدده مجلس الوزراء"],"a":0}]},{"n":"2","chapter":"","notes":[],"source":"يكون للكلمات والعبارات التالية، حيثما وردت في هذا القانون، المعاني المخصصة لها أدناه ما لم تدل القرينة على غير ذلك :\nالمنطقة: منطقة العقبة الاقتصادية الخاصة.\nالسلطة : سلطة المنطقة.\nالمجلس : مجلس المفوضين.\nالرئيس: رئيس المجلس.\nالمؤسسة المسجلة : الشخص المسجل لدى السلطة وفق أحكام هذا القانون.\nالمنطقة الجمركية: اراضي المملكة ومياهها الاقليمية باستثناء المنطقة.\nالاقليم اراضي محافظة العقبة التي تقع خارج حدود المنطقة ولا تدخل ضمن حدود وادي الاردن بمقتضى قانون تطوير وادي الاردن.\nالادخال: ادخال البضائع التي تخضع في المنطقة الجمركية للرسوم الجمركية والضرائب إلى المنطقة دون استيفاء مثل هذه الرسوم والضرائب على تلك البضائع.\nالاستيراد :دخول البضائع إلى المنطقة ، بما في ذلك الادخال ، باستثناء احضار البضائع إلى المنطقة من المنطقة الجمركية إذا تم فيها دفع الرسوم الجمركية والضرائب المستحقة على هذه البضائع.","title":"التعريفات","memo":"⭐ المجلس: مجلس المفوضين، والرئيس: رئيس المجلس\n⭐ المنطقة الجمركية: أراضي المملكة ومياهها الإقليمية باستثناء المنطقة\n⭐ الإقليم: أراضي محافظة العقبة خارج حدود المنطقة ولا تدخل ضمن حدود وادي الأردن\n⭐ الإدخال: إدخال البضائع الخاضعة للرسوم والضرائب في المنطقة الجمركية إلى المنطقة دون استيفائها","qs":[{"q":"يقصد بـ(المجلس) في قانون منطقة العقبة الاقتصادية الخاصة:","o":["مجلس المفوضين","مجلس الوزراء","مجلس إدارة سلطة إقليم العقبة","المجلس البلدي للعقبة"],"a":0},{"q":"تعرّف (المنطقة الجمركية) في القانون بأنها:","o":["أراضي المملكة ومياهها الإقليمية باستثناء المنطقة","أراضي محافظة العقبة خارج حدود المنطقة","المراكز الجمركية القائمة على حدود المنطقة","أراضي المنطقة ومياهها الإقليمية"],"a":0},{"q":"أراضي محافظة العقبة التي تقع خارج حدود المنطقة ولا تدخل ضمن حدود وادي الأردن يطلق عليها:","o":["الإقليم","المنطقة الجمركية","المنطقة","المنطقة الحرة"],"a":0},{"q":"يُعدّ إدخالُ بضائعَ تخضع في المنطقة الجمركية للرسوم الجمركية والضرائب إلى المنطقة دون استيفاء هذه الرسوم والضرائب:","o":["إدخالاً","تصديراً","إعادة تصدير","إدخالاً مؤقتاً"],"a":0}]},{"n":"3","chapter":"","notes":[],"source":"يهدف إنشاء المنطقة إلى تعزيز القدرة الاقتصادية في المملكة باستقطاب الانشطة الاقتصادية المختلفة وجذب الاستثمارات إليها .ركية إذا تم فيها دفع الرسوم الجمركية والضرائب المستحقة على هذه البضائع.","title":"أهداف إنشاء المنطقة","memo":"⭐ الهدف: تعزيز القدرة الاقتصادية في المملكة باستقطاب الأنشطة الاقتصادية المختلفة وجذب الاستثمارات","qs":[{"q":"يهدف إنشاء منطقة العقبة الاقتصادية الخاصة إلى:","o":["تعزيز القدرة الاقتصادية في المملكة باستقطاب الأنشطة الاقتصادية وجذب الاستثمارات","زيادة إيرادات الخزينة العامة من الرسوم الجمركية","حماية الصناعة المحلية من المنافسة الأجنبية","تنظيم حركة الموانئ في المملكة"],"a":0},{"q":"تسعى المنطقة لتعزيز القدرة الاقتصادية للمملكة من خلال:","o":["استقطاب الأنشطة الاقتصادية المختلفة وجذب الاستثمارات إليها","فرض رسوم إضافية على المستوردات","تقليص دور القطاع الخاص في التنمية","حصر النشاط الاقتصادي بالقطاع العام"],"a":0}]},{"n":"4","chapter":"","notes":[],"source":"تحدد بقرار من مجلس الوزراء بناء على تنسيب المجلس حدود المنطقة وله تعديل هذه الحدود وفقا لمتطلبات عمل السلطة ومقتضيات المصلحة العامة وينشر القرار وأي تعديل يطرا عليه في الجريدة الرسمية.","title":"تحديد حدود المنطقة","memo":"⭐ تحدد حدود المنطقة بقرار من مجلس الوزراء بناءً على تنسيب المجلس (مجلس المفوضين)\n⭐ لمجلس الوزراء تعديلها وفق متطلبات عمل السلطة والمصلحة العامة\n⭐ ينشر القرار وأي تعديل عليه في الجريدة الرسمية","qs":[{"q":"تحدد حدود منطقة العقبة الاقتصادية الخاصة بقرار من:","o":["مجلس الوزراء بناءً على تنسيب مجلس المفوضين","مجلس المفوضين بموافقة رئيس الوزراء","رئيس مجلس المفوضين","وزير المالية بناءً على تنسيب المجلس"],"a":0},{"q":"يجوز تعديل حدود المنطقة وفقاً لـ:","o":["متطلبات عمل السلطة ومقتضيات المصلحة العامة","طلب المؤسسات المسجلة في المنطقة","توصية دائرة الجمارك العامة","قرار من محافظ العقبة"],"a":0}]},{"n":"5","chapter":"","notes":[],"source":"يحدد بقرار من مجلس الوزراء بتنسيب من المجلس تاريخ بدء العمل في المنطقة ويتم نشر القرار في الجريدة الرسمية.","title":"تاريخ بدء العمل في المنطقة","memo":"⭐ يحدد تاريخ بدء العمل في المنطقة بقرار من مجلس الوزراء بتنسيب من المجلس\n⭐ ينشر القرار في الجريدة الرسمية","qs":[{"q":"يحدد تاريخ بدء العمل في المنطقة بقرار من:","o":["مجلس الوزراء بتنسيب من المجلس","المجلس بموافقة مجلس الوزراء","رئيس الوزراء","رئيس مجلس المفوضين"],"a":0}]},{"n":"6","chapter":"","notes":[],"source":"تسري على المنطقة أحكام التشريعات النافذة المفعول في المملكة ويعمل بأحكام هذا القانون عند تعارضها مع أي نص في تلك التشريعات.","title":"سريان التشريعات على المنطقة","memo":"⭐ تسري على المنطقة التشريعات النافذة في المملكة\n⭐ عند التعارض يعمل بأحكام قانون المنطقة","qs":[{"q":"إذا تعارض نص في تشريع نافذ في المملكة مع أحكام قانون منطقة العقبة الاقتصادية الخاصة فإنه:","o":["يعمل بأحكام قانون المنطقة","يعمل بأحكام التشريع النافذ في المملكة","يعرض الأمر على مجلس الوزراء للترجيح","يعمل بالتشريع الأحدث صدوراً"],"a":0}]},{"n":"7","chapter":"","notes":[],"source":"أ-تنشا في المملكة سلطة تسمى ( سلطة منطقة العقبة الاقتصادية الخاصة ) تتمتع بشخصية اعتبارية ذات استقلال مالي واداري ولها بهذه الصفة تملك الاموال المنقولة وغير المنقولة والقيام بجميع التصرفات القانونية اللازمة لتحقيق اهدافها بما في ذلك ابرام العقود وقبول المساعدات والهبات والتبرعات ولها حق التقاضي وينوب عنها في الاجراءات القضائية المحامي العام المدني او أي محام توكله لهذه الغاية.\nب-يكون مقر السلطة في المنطقة ولها ان تنشىء مكاتب ارتباط داخل المملكة وخارجها.\nج-ترتبط السلطة برئيس الوزراء.","title":"إنشاء السلطة وشخصيتها ومقرها","memo":"⭐ سلطة منطقة العقبة الاقتصادية الخاصة: شخصية اعتبارية ذات استقلال مالي وإداري\n⭐ ينوب عنها قضائياً المحامي العام المدني أو أي محامٍ توكله\n⭐ مقرها في المنطقة ولها مكاتب ارتباط داخل المملكة وخارجها\n⭐ ترتبط السلطة برئيس الوزراء","qs":[{"q":"ترتبط سلطة منطقة العقبة الاقتصادية الخاصة بـ:","o":["رئيس الوزراء","وزير المالية","وزير الصناعة والتجارة","وزير الداخلية"],"a":0},{"q":"ينوب عن السلطة في الإجراءات القضائية:","o":["المحامي العام المدني أو أي محامٍ توكله لهذه الغاية","رئيس ديوان التشريع والرأي","النائب العام حصراً","رئيس مجلس المفوضين شخصياً"],"a":0},{"q":"أي مما يلي صحيح بشأن مقر السلطة وفق القانون؟","o":["مقرها في المنطقة ولها إنشاء مكاتب ارتباط داخل المملكة وخارجها","مقرها في عمان ولها مكتب في العقبة","مقرها في المنطقة ولا يجوز لها إنشاء مكاتب خارج المملكة","يحدد مقرها بقرار من مجلس الوزراء"],"a":0}]},{"n":"8","chapter":"","notes":[],"source":"أ-تصبح السلطة الخلف القانوني والواقعي لكل من سلطة اقليم العقبة وبلدية العقبة وفقا لأحكام هذا القانون اعتبارا من التاريخ الذي يحدده مجلس الوزراء.\nب-تنتقل إلى السلطة جميع حقوق والتزامات كل من سلطة اقليم العقبة وبلدية العقبة وتلتزم السلطة بتنفيذ العقود والاتفاقيات التي تكون أي من هاتين الجهتين طرفا فيها في التاريخ الذي يحدده مجلس الوزراء وكانها معقودة مع السلطة.\nج-تنتقل إلى السلطة ملكية المنشات والعقارات العائدة إلى مؤسسة المناطق الحرة الواقعة داخل حدود المنطقة لقاء عوض يقرره مجلس الوزراء.\nد-ينقل إلى السلطة حكما جميع الموظفين والمستخدمين العاملين لدى كل من سلطة اقليم العقبة ومؤسسة المناطق الحرة في العقبة وبلدية العقبة.\nه-تعامل مؤسسة المدن الصناعية في المنطقة معاملة المؤسسة المسجلة ولا تسري أحكام قانونها النافذ المفعول داخل المنطقة وذلك مع عدم المساس بحقوق مؤسسة المدن الصناعية والالتزامات المترتبة عليها قبل نفاذ أحكام هذا القانون.","title":"السلطة خلفاً قانونياً","memo":"⭐ السلطة الخلف القانوني والواقعي لسلطة إقليم العقبة وبلدية العقبة اعتباراً من التاريخ الذي يحدده مجلس الوزراء\n⭐ تنتقل إليها منشآت وعقارات مؤسسة المناطق الحرة داخل المنطقة لقاء عوض يقرره مجلس الوزراء\n⭐ ينقل إليها حكماً موظفو سلطة إقليم العقبة ومؤسسة المناطق الحرة في العقبة وبلدية العقبة\n⭐ مؤسسة المدن الصناعية في المنطقة تعامل معاملة المؤسسة المسجلة","qs":[{"q":"تصبح السلطة الخلف القانوني والواقعي لكل من:","o":["سلطة إقليم العقبة وبلدية العقبة","مؤسسة الموانئ ودائرة الجمارك","مؤسسة المناطق الحرة ومؤسسة المدن الصناعية","محافظة العقبة وسلطة وادي الأردن"],"a":0},{"q":"تنتقل إلى السلطة ملكية المنشآت والعقارات العائدة لمؤسسة المناطق الحرة الواقعة داخل حدود المنطقة:","o":["لقاء عوض يقرره مجلس الوزراء","دون أي عوض","لقاء عوض يقرره مجلس المفوضين","لقاء عوض تقدره دائرة الأراضي والمساحة"],"a":0},{"q":"كيف تعامل مؤسسة المدن الصناعية في المنطقة وفق القانون؟","o":["معاملة المؤسسة المسجلة ولا تسري أحكام قانونها داخل المنطقة","تبقى خاضعة لقانونها النافذ داخل المنطقة","تنتقل ملكيتها إلى السلطة حكماً","تعامل معاملة الدوائر الحكومية"],"a":0}]},{"n":"9","chapter":"","notes":[],"source":"تتولى السلطة المهام التالية:\nأ-تنمية المنطقة وتاهيلها لاستقطاب الاستثمارات وايجاد بيئة استثمارية متطورة لتنشيط الصناعة والتجارة والسياحة والخدمات في المنطقة.\nب-زيادة فرص العمل للاردنيين والتنسيق والتعاون مع الجهات المستثمرة في المنطقة لتدريب الايدي العاملة الاردنية وتاهيلها ورفع كفاءتها واعطاء الاولوية لها في العمل.\nج-تعزيز دور القطاع الخاص بالمشاركة في تطوير المنطقة بما في ذلك توفير خدمات البنية التحتية وأي خدمات عامة.\nد-تشجيع المنافسة ومنع الاحتكار في الانشطة الاقتصادية المختلفة داخل المنطقة.\nه-تخطيط وتصميم مشروعات تطوير المنطقة في المجالات المختلفة وتنفيذها مباشرة او بواسطة الغير.\nو- حماية البيئة في المنطقة.\nز- تشجيع المؤسسات المسجلة على القيام بالبحث والتطوير ودعمه.","title":"مهام السلطة","memo":"⭐ تنمية المنطقة وإيجاد بيئة استثمارية متطورة\n⭐ زيادة فرص العمل للأردنيين وإعطاء الأولوية للأيدي العاملة الأردنية\n⭐ تشجيع المنافسة ومنع الاحتكار، وحماية البيئة، وتشجيع البحث والتطوير\n⭐ تخطيط مشروعات التطوير وتنفيذها مباشرة أو بواسطة الغير","qs":[{"q":"أي مما يلي ليس من مهام السلطة المنصوص عليها في المادة (9)؟","o":["فرض الحماية الجمركية على البضائع المنافسة","تشجيع المنافسة ومنع الاحتكار في الأنشطة الاقتصادية","حماية البيئة في المنطقة","تشجيع المؤسسات المسجلة على البحث والتطوير ودعمه"],"a":0},{"q":"تنفذ السلطة مشروعات تطوير المنطقة في المجالات المختلفة:","o":["مباشرة أو بواسطة الغير","مباشرة فقط","بواسطة القطاع الخاص حصراً","بواسطة الوزارات المختصة فقط"],"a":0},{"q":"فيما يتعلق بالأيدي العاملة، تتولى السلطة:","o":["زيادة فرص العمل للأردنيين وإعطاء الأولوية للأيدي العاملة الأردنية","استقدام العمالة الوافدة دون قيود","تحديد الحد الأدنى للأجور في المنطقة","منع تشغيل غير الأردنيين في المنطقة"],"a":0}]},{"n":"10","chapter":"","notes":[],"source":"تتولى السلطة المسؤوليات التالية:\nأ-تتولى السلطة المسؤوليات التالية:\n1-ادارة المنطقة ومتابعة شؤونها وفقا لصلاحياتها بمقتضى هذا القانون والانظمة الصادرة بمقتضاه.\n2-وضع الخطط والبرامج اللازمة لتطوير المنطقة.\n3-وضع الاسس الواجبة التطبيق على الاستثمار في المنطقة.\n4-تسجيل المؤسسات التي ترغب في الاستفادة من الميزات والاعفاءات المقررة بموجب هذا القانون.\n5-ترويج المنطقة بالتنسيق والتعاون مع الجهات ذات العلاقة.\nب-على الرغم مما ورد في أي تشريع اخر ، تمارس السلطة داخل حدود المنطقة ووفقا لأحكام هذا القانون المهام والصلاحيات المتعلقة بما يلي:\n1-تنظيم الانشطة الاقتصادية والرقابة عليها للتأكد من تقيدها بأحكام هذا القانون والانظمة الصادرة بمقتضاه والتعليمات الصادرة بموجب أي منها بما في ذلك شؤون الصحة العامة والسلامة العامة ذات العلاقة بهذه الانشطة.\n2-اصدار التصاريح والشهادات وأي موافقة اخرى تتعلق بممارسة الانشطة الاقتصادية في المنطقة وفقا لأحكام هذا القانون والانظمة الصادرة بمقتضاه\n3-تنظيم المدن والقرى والابنية.\n4-الشؤون البلدية.\n5-حماية البيئة ومصادر المياه والموارد الطبيعية والتنوع البيولوجي.\n6-الرقابة على الغذاء والدواء المستورد إلى المنطقة او المصدر منها والرقابة والتفتيش على جميع الاماكن التي يتم فيها الذبح واعداد الغذاء ومشتقاته وتصنيعه وتداوله وبيعه وتقديمه ولهذه الغاية يمارس الرئيس صلاحيات الوزير والمفوض المختص صلاحيات المدير المقررة لكل منهما في قانون الرقابة على الغذاء المعمول به والانظمة الصادرة بمقتضاه.\n7-الامور والاجراءات الجمركية.\n8-تحصيل الضرائب والرسوم والغرامات وبدل الخدمات المنصوص عليها في هذا القانون والانظمة الصادرة بمقتضاه والتعليمات الصادرة بموجب أي منها.\n9-شؤون العمل والعمال.\n10-أي صلاحيات منوطة بجهات رسمية اخرى يخولها مجلس الوزراء للسلطة.","title":"مسؤوليات السلطة وصلاحياتها داخل المنطقة","memo":"⭐ من مسؤولياتها: إدارة المنطقة، وضع الخطط، وضع أسس الاستثمار، تسجيل المؤسسات، الترويج\n⭐ على الرغم من أي تشريع آخر تمارس داخل المنطقة: تنظيم المدن والقرى والأبنية، الشؤون البلدية، الأمور الجمركية، تحصيل الضرائب والرسوم، شؤون العمل والعمال\n⭐ في الرقابة على الغذاء: يمارس الرئيس صلاحيات الوزير، والمفوض المختص صلاحيات المدير\n⭐ أي صلاحيات لجهات رسمية أخرى يخولها مجلس الوزراء للسلطة","qs":[{"q":"لغايات الرقابة على الغذاء والدواء في المنطقة، يمارس رئيس مجلس المفوضين صلاحيات:","o":["الوزير المقررة في قانون الرقابة على الغذاء","المدير المقررة في قانون الرقابة على الغذاء","المحافظ المقررة في التشريعات النافذة","الحاكم الإداري"],"a":0},{"q":"في مجال الرقابة على الغذاء داخل المنطقة، يمارس المفوض المختص صلاحيات:","o":["المدير","الوزير","الحاكم الإداري","رئيس البلدية"],"a":0},{"q":"أي مما يلي لا يعد من المهام والصلاحيات التي تمارسها السلطة داخل حدود المنطقة وفق المادة (10/ب)؟","o":["تعيين مدقق حسابات ديوان المحاسبة","تنظيم المدن والقرى والأبنية","الأمور والإجراءات الجمركية","شؤون العمل والعمال"],"a":0},{"q":"الجهة التي تخول السلطة أي صلاحيات منوطة بجهات رسمية أخرى هي:","o":["مجلس الوزراء","مجلس المفوضين","رئيس الوزراء","مجلس الأمة"],"a":0}]},{"n":"11","chapter":"","notes":[],"source":"أ-تتولى السلطة اضافة إلى مهامها في المنطقة مسؤولية تنمية الاقليم اقتصاديا واجتماعيا ووضع الخطط والبرامج اللازمة لذلك وتمارس لهذه الغاية أي صلاحية مخولة لها بموجب هذا القانون حسبما تتطلبه تنمية الاقليم ووفق نظام يصدر لهذه الغاية.\nب-وتتولى السلطة صلاحية ادارة املاك الدولة في الاقليم وفقا لأحكام قانون ادارة املاك الدولة النافذ المفعول والانظمة الصادرة بمقتضاه شريطة مراعاة ما يلي:\n1-ادارة الاثار والمواقع الاثرية الواقعة ضمن الاقليم وفقا لقانون الاثار النافذ المفعول.\n2-استيفاء دائرة الاراضي والمساحة للرسوم المترتبة على تنفيذ جميع معاملات تسجيل اراضي الدولة.\n3-رد الاموال المتأتية نتيجة لايجار الاراضي او تفويضها او أي تصرف اخر بشأنها إلى الخزينة العامة.\n4-كما تتولى السلطة حماية البيئة في الاقليم وفقا لأحكام هذا القانون والانظمة الصادرة بمقتضاه وأي تشريع ذي علاقة نافذ المفعول.","title":"مسؤولية السلطة في الإقليم","memo":"⭐ تتولى السلطة تنمية الإقليم اقتصادياً واجتماعياً وفق نظام يصدر لهذه الغاية\n⭐ تدير أملاك الدولة في الإقليم وفق قانون إدارة أملاك الدولة\n⭐ الآثار تدار وفق قانون الآثار، ودائرة الأراضي تستوفي رسوم تسجيل أراضي الدولة\n⭐ ترد أموال إيجار الأراضي أو تفويضها إلى الخزينة العامة","qs":[{"q":"الأموال المتأتية من إيجار أراضي الدولة في الإقليم أو تفويضها:","o":["ترد إلى الخزينة العامة","تؤول إلى موازنة السلطة","تؤول إلى بلدية العقبة","توزع مناصفة بين السلطة والخزينة"],"a":0},{"q":"الجهة التي تستوفي الرسوم المترتبة على معاملات تسجيل أراضي الدولة في الإقليم هي:","o":["دائرة الأراضي والمساحة","السلطة","وزارة المالية","مجلس المفوضين"],"a":0},{"q":"تتولى السلطة إدارة أملاك الدولة في الإقليم وفقاً لأحكام:","o":["قانون إدارة أملاك الدولة والأنظمة الصادرة بمقتضاه","قانون الاستملاك","قانون تنظيم المدن والقرى والأبنية","تعليمات يصدرها مجلس المفوضين"],"a":0}]},{"n":"12","chapter":"","notes":[],"source":"أ-يتولى ادارة السلطة والاشراف على شؤونها مجلس يسمى (مجلس المفوضين) يتالف من ستة اعضاء متفرغين بمن فيهم الرئيس ونائبه يعينون بقرار من مجلس الوزراء بناء على تنسيب رئيس الوزراء لمدة اربع سنوات قابلة للتجديد على ان يقترن القرار بالارادة الملكية السامية.\nب-تكون مدة العضوية في تاليف اول مجلس سنتين لنصف اعضائه واربع سنوات للنصف الاخر من بينهم الرئيس ونائبه.\nج-لمجلس الوزراء وخلال مدة المجلس انهاء عضوية أي من اعضائه وتعيين بديل يحل محله وذلك بالطريقة المنصوص عليها في الفقرة (أ) من هذه المادة.\nد-تحدد الرواتب والعلاوات وسائر الحقوق المالية للرئيس واعضاء المجلس بقرار من مجلس الوزراء بناء على تنسيب رئيس الوزراء.","title":"تشكيل مجلس المفوضين","memo":"⭐ مجلس المفوضين: 6 أعضاء متفرغين بمن فيهم الرئيس ونائبه\n⭐ يعينون بقرار مجلس الوزراء بتنسيب رئيس الوزراء لمدة 4 سنوات قابلة للتجديد ويقترن القرار بالإرادة الملكية\n⭐ أول مجلس: سنتان لنصف الأعضاء و4 سنوات للنصف الآخر ومنهم الرئيس ونائبه\n⭐ الرواتب والحقوق المالية بقرار مجلس الوزراء بتنسيب رئيس الوزراء","qs":[{"q":"يتألف مجلس المفوضين من:","o":["ستة أعضاء متفرغين بمن فيهم الرئيس ونائبه","سبعة أعضاء متفرغين بمن فيهم الرئيس","خمسة أعضاء متفرغين إضافة إلى الرئيس","تسعة أعضاء غير متفرغين"],"a":0},{"q":"مدة عضوية مجلس المفوضين هي:","o":["أربع سنوات قابلة للتجديد","سنتان قابلة للتجديد","خمس سنوات غير قابلة للتجديد","ثلاث سنوات قابلة للتجديد مرة واحدة"],"a":0},{"q":"في تأليف أول مجلس للمفوضين، كانت مدة العضوية لنصف الأعضاء:","o":["سنتين","سنة واحدة","ثلاث سنوات","أربع سنوات"],"a":0},{"q":"يعين أعضاء مجلس المفوضين بقرار من:","o":["مجلس الوزراء بناءً على تنسيب رئيس الوزراء مقترناً بالإرادة الملكية","رئيس الوزراء مقترناً بالإرادة الملكية","مجلس الوزراء بناءً على تنسيب وزير المالية","مجلس الأمة بناءً على تنسيب الحكومة"],"a":0}]},{"n":"13","chapter":"","notes":[],"source":"أ-يشترط فيمن يعين في المجلس ان يكون:\n1-اردني الجنسية.\n2-من ذوي الكفاءة والخبرة والاختصاص.\n3-غير محكوم بجناية او بجنحة مخلة بالشرف.\nب-يحظر على الرئيس واعضاء المجلس وازواجهم وفروعهم من الدرجة الاولى ان يكون لأي منهم خلال مدة عضويته أي منفعة مع السلطة بأي صورة كانت.\nلا يجوز ان يكون للرئيس وأي من اعضاء المجلس أي علاقة تجارية مع أي مؤسسة مسجلة او أي مستثمر في المنطقة.\nعلى الرئيس وكل عضو في المجلس تقديم تصريح خطي حين تعيينه وقبل مباشرته لمهامه ويؤكد انتفاء أي منفعة له او أي نشاط تجاري مما ورد ذكره في البندين(1)،(2) من هذه الفقرة وذلك تحت طائلة المسؤولية القانونية وفصله من عضوية المجلس.\nج-يؤدي الرئيس واعضاء المجلس امام رئيس الوزراء قبل مباشرة مهامهم القسم التالي:\n(اقسم بالله العظيم ان اكون مخلصا للملك والوطن وان احترم القوانين والانظمة المعمول بها وان اقوم بالمهام والواجبات الموكولة الي بشرف وامانة واخلاص).","title":"شروط عضوية المجلس وموانعها","memo":"⭐ الشروط: أردني، ذو كفاءة وخبرة واختصاص، غير محكوم بجناية أو جنحة مخلة بالشرف\n⭐ يحظر على الرئيس والأعضاء وأزواجهم وفروعهم من الدرجة الأولى أي منفعة مع السلطة\n⭐ لا علاقة تجارية مع أي مؤسسة مسجلة أو مستثمر في المنطقة\n⭐ تصريح خطي عند التعيين، والقسم أمام رئيس الوزراء","qs":[{"q":"يؤدي رئيس وأعضاء مجلس المفوضين القسم قبل مباشرة مهامهم أمام:","o":["رئيس الوزراء","جلالة الملك","رئيس المجلس القضائي","مجلس الوزراء"],"a":0},{"q":"يمتد حظر المنفعة مع السلطة خلال مدة العضوية ليشمل الرئيس والأعضاء و:","o":["أزواجهم وفروعهم من الدرجة الأولى","أقاربهم حتى الدرجة الثالثة","أزواجهم فقط","فروعهم وأصولهم حتى الدرجة الثانية"],"a":0},{"q":"أي مما يلي ليس من شروط التعيين في مجلس المفوضين؟","o":["أن يكون حاصلاً على شهادة الدكتوراه","أن يكون أردني الجنسية","أن يكون من ذوي الكفاءة والخبرة والاختصاص","ألا يكون محكوماً بجناية أو بجنحة مخلة بالشرف"],"a":0},{"q":"حالة عملية: عضو في مجلس المفوضين تبين أن له علاقة تجارية مع مؤسسة مسجلة ولم يصرح بها في تصريحه الخطي عند تعيينه. ما الأثر وفق القانون؟","o":["يتعرض للمسؤولية القانونية والفصل من عضوية المجلس","يكتفى بإنذاره خطياً","توقف عضويته لمدة سنة","لا أثر لذلك إذا كانت العلاقة سابقة لتعيينه"],"a":0}]},{"n":"14","chapter":"","notes":[],"source":"يصدر مجلس الوزراء عند نفاذ أحكام هذا القانون القرارات اللازمة لاقامة المنطقة وبدء اعمالها وعلى وجه الخصوص ما يلي:\nأ-تعيين الرئيس ونائبه واعضاء المجلس.\nب-تحديد اجراءات وتواريخ انتقال مسؤوليات ومهام سلطة اقليم العقبة إلى السلطة وذلك بناء على تنسيب من المجلس ووفق الخطة التي يضعها لهذه الغاية.\nت- تحديد تاريخ بدء ممارسة المجلس لوظائف مجلس بلدية العقبة بتنسيب من المجلس وما يستدعي من اجراءات لهذه الغاية.\nث- اجراءات نقل الموظفين والمستخدمين العاملين في سلطة اقليم العقبة ومؤسسة المناطق الحرة في العقبة وبلدية العقبة إلى السلطة استنادا إلى تنسيب المجلس.\nج-أي قرار يراه ضروريا لقيام السلطة بمهامها خلال المدة التي تسبق تاريخ بدء العمل في المنطقة.","title":"قرارات مجلس الوزراء لإقامة المنطقة","memo":"⭐ يصدر مجلس الوزراء القرارات اللازمة لإقامة المنطقة: تعيين الرئيس ونائبه والأعضاء\n⭐ تحديد إجراءات وتواريخ انتقال مهام سلطة إقليم العقبة بتنسيب المجلس\n⭐ تحديد تاريخ ممارسة المجلس لوظائف مجلس بلدية العقبة بتنسيب المجلس\n⭐ نقل موظفي سلطة الإقليم ومؤسسة المناطق الحرة وبلدية العقبة بتنسيب المجلس","qs":[{"q":"الجهة التي تحدد تاريخ بدء ممارسة مجلس المفوضين لوظائف مجلس بلدية العقبة هي:","o":["مجلس الوزراء بتنسيب من المجلس","وزير الشؤون البلدية","رئيس مجلس المفوضين","المجلس بموافقة رئيس الوزراء"],"a":0},{"q":"أي مما يلي ليس من القرارات التي يصدرها مجلس الوزراء عند نفاذ القانون وفق المادة (14)؟","o":["تسجيل المؤسسات الراغبة بالاستفادة من الإعفاءات","تعيين الرئيس ونائبه وأعضاء المجلس","تحديد إجراءات وتواريخ انتقال مسؤوليات سلطة إقليم العقبة إلى السلطة","إجراءات نقل الموظفين العاملين في بلدية العقبة إلى السلطة"],"a":0}]},{"n":"15","chapter":"","notes":[],"source":"يمارس المجلس المهام والصلاحيات التالية:\nأ-رسم السياسة العامة لتنمية المنطقة بموافقة مجلس الوزراء ، واقرار الخطط والبرامج اللازمة لتنفيذها.\nب-تخصيص المناطق الاستثمارية في المنطقة وتحديد استعمال الاراضي فيها على اساس القطاعات المختلفة.\nج-اقرار الهيكل التنظيمي للجهاز التنفيذي في السلطة وجدول تشكيلات الوظائف والوصف الوظيفي لها.\nد-الاشراف على الجهاز التنفيذي للسلطة وسير العمل فيها بما يضمن حسن الاداء.\nه-وظائف المجلس البلدي وفقا لأحكام قانون البلديات النافذ المفعول والانظمة الصادرة بمقتضاه ولهذه الغاية يمارس الرئيس الصلاحيات المقررة للوزير بمقتضى هذه التشريعات.\nو- اختصاصات مجلس التنظيم الاعلى ولجنتي التنظيم اللوائية والمحلية بمقتضى قانون تنظيم المدن والقرى والابنية الساري المفعول والانظمة الصادرة استنادا له.\nز- استملاك الاراضي والعقارات اللازمة لاعمال السلطة او لتنمية المنطقة وفقا لأحكام قانون الاستملاك النافذ المفعول.\nح- اقرار العقود والاتفاقيات التي تكون السلطة طرفا فيها.\nط- اعداد مشروعات التشريعات اللازمة لاعمال السلطة ورفعها لمجلس الوزراء.\nي- التنسيب لمجلس الوزراء بتعيين مدقق حسابات قانوني للسلطة.\nك- اقرار مشروع الموازنة التقديرية السنوية للسلطة ورفعه إلى مجلس الوزراء للمصادقة عليه.\nل- اقرار التقرير السنوي عن نشاط السلطة وميزانيتها وحساباتها الختامية عن السنة المالية المنتهية ورفعها إلى مجلس الوزراء.\nم- وضع التعليمات المتعلقة بعمل السلطة واجراءاتها وبخاصة ما يلي:\n1-تنظيم انشطة المؤسسات المسجلة والرقابة عليها.\n2-تنظيم نشاط المستثمرين في المنطقة.\n3-تحصيل الضرائب والرسوم والغرامات وبدل الخدمات المقررة في المنطقة.\n4-اصدار شهادات المنشا للبضائع المنتجة في المنطقة والجهات المخولة باصدارها.\n5-تحديد البدل الذي تستوفيه السلطة مقابل الخدمات التي تقدمها لأي جهة ذات علاقة بانشطتها.\n6-وضع الاسس اللازمة لتصويب الاجراءات التي تمت قبل تاريخ بدء العمل في المنطقة بصورة مخالفة لأحكام التشريعات المتعلقة برخص المهن النافذة المفعول.","title":"مهام مجلس المفوضين وصلاحياته","memo":"⭐ رسم السياسة العامة لتنمية المنطقة بموافقة مجلس الوزراء\n⭐ يمارس وظائف المجلس البلدي ويمارس الرئيس صلاحيات الوزير، ويمارس اختصاصات مجلس التنظيم الأعلى ولجنتي التنظيم\n⭐ التنسيب لمجلس الوزراء بتعيين مدقق حسابات قانوني، وإقرار الموازنة ورفعها لمجلس الوزراء للمصادقة\n⭐ الاستملاك وفق قانون الاستملاك، وإقرار العقود، ووضع التعليمات","qs":[{"q":"يرسم مجلس المفوضين السياسة العامة لتنمية المنطقة:","o":["بموافقة مجلس الوزراء","بموافقة رئيس الوزراء","بموافقة مجلس الأمة","دون الحاجة لموافقة أي جهة"],"a":0},{"q":"لغايات ممارسة مجلس المفوضين وظائف المجلس البلدي، يمارس رئيس المجلس الصلاحيات المقررة لـ:","o":["الوزير","رئيس البلدية","المحافظ","مجلس التنظيم الأعلى"],"a":0},{"q":"دور مجلس المفوضين في تعيين مدقق حسابات قانوني للسلطة هو:","o":["التنسيب لمجلس الوزراء بتعيينه","تعيينه مباشرة بقرار منه","المصادقة على تعيين ديوان المحاسبة له","اقتراحه على رئيس الوزراء للموافقة"],"a":0},{"q":"يقر مجلس المفوضين مشروع الموازنة التقديرية السنوية للسلطة ويرفعه للمصادقة عليه إلى:","o":["مجلس الوزراء","رئيس الوزراء","وزير المالية","ديوان المحاسبة"],"a":0}]},{"n":"16","chapter":"","notes":[],"source":"أ-يجتمع المجلس مرتين على الاقل كل شهر بدعوة من الرئيس او نائبه عند غياب الرئيس ويكون اجتماعه قانونيا بحضور اغلبية اعضائه على ان يكون من بينهم الرئيس او نائبه.\nب-يتخذ المجلس قراراته باغلبية اصوات اعضائه الحاضرين في الاجتماع على ان لا تقل عن ثلاثة اصوات ولا يجوز للعضو الامتناع عن التصويت وعلى العضو المخالف تسجيل مخالفته خطيا في محضر الاجتماع والتوقيع عليها وعند تساوي الاصوات يرجح الرأي الذي صوت معه رئيس الاجتماع.\nج-تحدد بتعليمات يصدرها المجلس اجراءات تنظيم عمل المجلس واجتماعاته وسائر اموره الاخرى.","title":"اجتماعات المجلس وقراراته","memo":"⭐ يجتمع مرتين على الأقل كل شهر بدعوة الرئيس أو نائبه عند غيابه\n⭐ النصاب: أغلبية الأعضاء على أن يكون بينهم الرئيس أو نائبه\n⭐ القرار بأغلبية الحاضرين على ألا تقل عن 3 أصوات، ولا يجوز الامتناع عن التصويت\n⭐ عند التساوي يرجح جانب رئيس الاجتماع","qs":[{"q":"يجتمع مجلس المفوضين:","o":["مرتين على الأقل كل شهر","مرة واحدة على الأقل كل شهر","مرة كل أسبوعين على الأقل","أربع مرات على الأقل كل شهر"],"a":0},{"q":"يتخذ مجلس المفوضين قراراته بأغلبية أصوات الحاضرين على ألا تقل عن:","o":["ثلاثة أصوات","أربعة أصوات","صوتين","خمسة أصوات"],"a":0},{"q":"حالة عملية: حضر اجتماع مجلس المفوضين أربعة أعضاء من بينهم نائب الرئيس، وتساوت الأصوات، وأراد أحد الأعضاء الامتناع عن التصويت. ما الحكم؟","o":["لا يجوز الامتناع عن التصويت، ويرجح الرأي الذي صوت معه رئيس الاجتماع","يجوز الامتناع ويؤجل القرار للاجتماع التالي","يجوز الامتناع ويعد القرار مرفوضاً عند التساوي","لا يجوز الامتناع ويعرض الأمر على رئيس الوزراء عند التساوي"],"a":0}]},{"n":"17","chapter":"","notes":[],"source":"أ-\n1-للمجلس ان يتعاقد مع الجهات المؤهلة فنيا وماليا لتطوير المنطقة او تشغيل او ادارة أي من مرافقها العامة على ان تحدد اسس التعاقد وشروطه بموجب نظام خاص يوضع لهذه الغاية.\n2-على الرغم مما ورد في أي تشريع اخر تكون السلطة مسؤولة عن تنظيم ومراقبة وتطوير ميناء العقبة ومطارها وأي من خدمات المرافق العامة في المنطقة وللمجلس بموافقة من مجلس الوزراء الحق في التعاقد مع أي جهة مؤهلة فنيا وماليا او أي من الجهات المشار إليها في البند (1) من هذه الفقرة وذلك لمقاصد تطوير او ادارة أي منها شريطة مشاركة الجهات ذات العلاقة بمقتضى تشريعاتها النافذة في المفاوضات التي تجري مع الجهات المؤهلة وحسبما يقرره مجلس الوزراء بهذا الشأن . ولا يعتبر العقد الذي يتم التوصل اليه نتيجة هذه المفاوضات نافذا الا بعد موافقة من مجلس الوزراء.\n3-للمجلس ان يؤسس شركة يتاح للجهات المؤهلة المتعاقد معها وفق أحكام البندين (1) و (2) من هذه الفقرة فرصة المساهمة فيها لتتولى عمليات التطوير او الادارة وفقا لشروط العقد الذي يتم التوصل اليه معها.\n4-وللمجلس الاتفاق مع أي جهة يتم التعاقد معها وفقا لأحكام البندين (1) و(2) من هذه الفقرة او مع ادارة الشركة المشار إليها في البند (3) منها ليعهد إليها بادارة المشاريع وخدمات المرافق موضع التطوير ويجوز له تأجير هذه المشاريع لها او السماح لها باستثمارها ويخضع أي اتفاق بهذا الشأن إلى موافقة مجلس الوزراء.\n5-يشترط في أي تعاقد او اتفاق تتوصل اليه السلطة وفقا لأحكام هذه الفقرة ان يتم بمقتضى أحكام نظام اللوازم والاشغال المعمول به في السلطة.\nب-للمجلس بموافقة مجلس الوزراء الاقتراض لتمويل مشروعات السلطة وانشطتها من مصادر داخلية او خارجية بما في ذلك اصدار سندات دين لهذه الغاية.","title":"تعاقد المجلس والاقتراض","memo":"⭐ للمجلس التعاقد مع جهات مؤهلة فنياً ومالياً لتطوير المنطقة أو تشغيل مرافقها، وأسس التعاقد بنظام خاص\n⭐ السلطة مسؤولة عن تنظيم ومراقبة وتطوير ميناء العقبة ومطارها؛ والتعاقد بشأنها بموافقة مجلس الوزراء ولا ينفذ العقد إلا بموافقته\n⭐ للمجلس تأسيس شركة تساهم فيها الجهات المتعاقد معها\n⭐ الاقتراض وإصدار سندات الدين بموافقة مجلس الوزراء","qs":[{"q":"لا يعتبر العقد الذي يتم التوصل إليه نتيجة المفاوضات لتطوير ميناء العقبة أو مطارها نافذاً إلا بعد موافقة:","o":["مجلس الوزراء","مجلس المفوضين","رئيس الوزراء","وزير النقل"],"a":0},{"q":"يجوز لمجلس المفوضين الاقتراض لتمويل مشروعات السلطة بما في ذلك إصدار سندات دين:","o":["بموافقة مجلس الوزراء ومن مصادر داخلية أو خارجية","بقرار منه دون موافقة أي جهة","بموافقة وزير المالية ومن مصادر داخلية فقط","بموافقة البنك المركزي ومن مصادر خارجية فقط"],"a":0},{"q":"يشترط في أي تعاقد أو اتفاق تتوصل إليه السلطة وفق المادة (17/أ) أن يتم بمقتضى:","o":["نظام اللوازم والأشغال المعمول به في السلطة","نظام اللوازم الحكومي العام","قانون الشراكة بين القطاعين العام والخاص","تعليمات يصدرها رئيس الوزراء"],"a":0}]},{"n":"18","chapter":"","notes":[],"source":"أ-يمارس الرئيس بصفته الرئيس التنفيذي للسلطة المهام والصلاحيات التالية:\n1-تنفيذ قرارات المجلس.\n2-الاشراف على الشؤون الادارية والمالية وشؤون اللوازم والاشغال في السلطة.\n3-توقيع العقود والاتفاقيات التي تبرمها السلطة مع الغير.\n4-اعداد مشروع الموازنة التقديرية السنوية للسلطة وجدول تشكيلات الوظائف فيها.\n5-اعداد التقرير السنوي عن نشاط السلطة وميزانيتها وحساباتها الختامية عن السنة المالية المنتهية.\n6-أي صلاحيات اخرى مخولة اليه بمقتضى الانظمة الصادرة استنادا لهذا القانون او التي يفوضه بها المجلس خطيا.\n7-صلاحيات وزير النقل بموجب قانون مؤسسة الموانئ او أي تشريع اخر نافذ المفعول ذي علاقة بقطاع النقل داخل المنطقة باستثناء ما يتعلق بالنقل البحري دون خدماته.\n8-صلاحيات المحافظ في محافظة العقبة بموجب التشريعات النافذة المفعول إذا لم يعين وزير الداخلية وبموافقة من رئيس الوزراء محافظا لها حيث يتم في حالة تعيينه وضع مذكرة تفاهم بين الوزير ورئيس مجلس المفوضين يقرها رئيس الوزراء ويراعيها المحافظ في قيامه بمهامه بمقتضى التشريعات المعمول بها وإذا نشا خلاف بين الطرفين في تطبيق المذكرة يرفع الامر إلى رئيس الوزراء للبت فيه.\nب-يمثل الرئيس السلطة لدى الغير.\nج-للرئيس تفويض أي من صلاحياته المنصوص عليها في هذا القانون والانظمة الصادرة بمقتضاه لنائبه او أي عضو في المجلس او أي موظف في السلطة على ان يكون التفويض خطيا ومحددا.","title":"مهام الرئيس وصلاحياته","memo":"⭐ الرئيس هو الرئيس التنفيذي للسلطة ويمثلها لدى الغير\n⭐ يمارس صلاحيات وزير النقل داخل المنطقة باستثناء النقل البحري دون خدماته\n⭐ يمارس صلاحيات المحافظ إذا لم يعين وزير الداخلية بموافقة رئيس الوزراء محافظاً؛ وعند التعيين مذكرة تفاهم يقرها رئيس الوزراء\n⭐ التفويض لنائبه أو عضو أو موظف بشرط أن يكون خطياً ومحدداً","qs":[{"q":"يمارس رئيس مجلس المفوضين داخل المنطقة صلاحيات وزير النقل باستثناء ما يتعلق بـ:","o":["النقل البحري دون خدماته","النقل الجوي","النقل البري","خدمات الموانئ"],"a":0},{"q":"يمارس رئيس مجلس المفوضين صلاحيات المحافظ في محافظة العقبة في حالة:","o":["عدم تعيين وزير الداخلية محافظاً لها بموافقة رئيس الوزراء","غياب المحافظ لأكثر من شهر","تفويضه من وزير الداخلية خطياً","صدور قرار من مجلس الوزراء بذلك"],"a":0},{"q":"إذا نشأ خلاف بين وزير الداخلية ورئيس مجلس المفوضين في تطبيق مذكرة التفاهم الخاصة بمهام المحافظ يرفع الأمر إلى:","o":["رئيس الوزراء للبت فيه","مجلس الوزراء","المحكمة الإدارية","محافظ العقبة"],"a":0},{"q":"يشترط في تفويض الرئيس لأي من صلاحياته أن يكون:","o":["خطياً ومحدداً","خطياً ولمدة لا تزيد على سنة","بموافقة مجلس الوزراء","لنائبه فقط"],"a":0}]},{"n":"19","chapter":"","notes":[],"source":"تتكون الموارد للسلطة مما يلي:\nأ-المبالغ السنوية التي ترصد لها في الموازنة العامة.\nب-أي رسوم او ضرائب او عوائد تتاتى للسلطة وفقا لأحكام هذا القانون والانظمة الصادرة بمقتضاه.\nج-أي بدل تتقاضاه السلطة مقابل الخدمات التي تقدمها للغير.\nد-الغرامات والتعويضات المدنية المتأتية من تطبيق العقوبات على مخالفة أي من أحكام هذا القانون والقوانين المعمول بها في المنطقة بما في ذلك تطبيق العقوبات المنصوص عليها في المادة (39) من هذا القانون.\nه-القروض التي تحصل عليها.\nو- المساعدات والهبات والتبرعات التي ترد إليها على ان تؤخذ موافقة مجلس الوزراء إذا كان مصدرها غير اردني.\nز- المبالغ المتأتية للسلطة من التصرف بموجوداتها وفق الاصول القانونية المقررة.\nح- أي مورد من أي مصدر اخر يقبله المجلس ويوافق عليه مجلس الوزراء.","title":"موارد السلطة","memo":"⭐ المبالغ السنوية في الموازنة العامة، الرسوم والضرائب والعوائد، بدل الخدمات، الغرامات والتعويضات، القروض\n⭐ المساعدات والهبات والتبرعات: موافقة مجلس الوزراء إذا كان مصدرها غير أردني\n⭐ أي مورد آخر يقبله المجلس ويوافق عليه مجلس الوزراء","qs":[{"q":"تشترط موافقة مجلس الوزراء لقبول المساعدات والهبات والتبرعات التي ترد للسلطة إذا كان:","o":["مصدرها غير أردني","مبلغها يزيد على مليون دينار","مصدرها جهة حكومية أردنية","مقدمها مؤسسة مسجلة في المنطقة"],"a":0},{"q":"أي مما يلي ليس من موارد السلطة المنصوص عليها في القانون؟","o":["حصة من أرباح المؤسسات المسجلة","المبالغ السنوية التي ترصد لها في الموازنة العامة","القروض التي تحصل عليها","أي بدل تتقاضاه مقابل الخدمات التي تقدمها للغير"],"a":0},{"q":"يعد من موارد السلطة أي مورد من مصدر آخر بشرط:","o":["أن يقبله المجلس ويوافق عليه مجلس الوزراء","أن يوافق عليه رئيس الوزراء","أن يقبله رئيس المجلس","أن يوافق عليه وزير المالية"],"a":0}]},{"n":"20","chapter":"","notes":[],"source":"أ-تبدا السنة المالية للسلطة في اليوم الاول من شهر كانون الثاني من كل سنة وتنتهي في الحادي والثلاثين من شهر كانون اول من السنة ذاتها.\nب-تكون للسلطة موازنة مستقلة يقرها المجلس ويصادق عليها مجلس الوزراء.\nج-يحول إلى الخزينة العامة أي فائض يتحقق في موازنة السلطة السنوية وذلك مع مراعاة التزامات السلطة المتعلقة بنفقات مشاريعها المستقبلية.\nد-يقوم ديوان المحاسبة بتدقيق لاحق على حسابات السلطة ويجوز لها تعيين مدقق حسابات قانوني ويرفع تقريرا بنتائج تدقيقه إلى مجلس الوزراء.","title":"السنة المالية والموازنة والتدقيق","memo":"⭐ السنة المالية من 1 كانون الثاني إلى 31 كانون الأول\n⭐ موازنة مستقلة يقرها المجلس ويصادق عليها مجلس الوزراء\n⭐ يحول الفائض إلى الخزينة العامة مع مراعاة التزامات المشاريع المستقبلية\n⭐ ديوان المحاسبة يقوم بتدقيق لاحق، ويجوز تعيين مدقق قانوني يرفع تقريره لمجلس الوزراء","qs":[{"q":"يحول أي فائض يتحقق في موازنة السلطة السنوية إلى:","o":["الخزينة العامة مع مراعاة التزامات السلطة بنفقات مشاريعها المستقبلية","حساب احتياطي خاص بالسلطة","صندوق تنمية الإقليم","الموازنة التقديرية للسنة التالية للسلطة حصراً"],"a":0},{"q":"نوع التدقيق الذي يقوم به ديوان المحاسبة على حسابات السلطة هو:","o":["تدقيق لاحق","تدقيق مسبق","تدقيق مسبق ولاحق","لا يخضع حساباتها لتدقيق ديوان المحاسبة"],"a":0},{"q":"يرفع مدقق الحسابات القانوني الذي تعينه السلطة تقريراً بنتائج تدقيقه إلى:","o":["مجلس الوزراء","مجلس المفوضين","ديوان المحاسبة","رئيس الوزراء"],"a":0}]},{"n":"21","chapter":"","notes":[],"source":"أ-تتمتع السلطة بالاعفاءات والتسهيلات المقررة للوزارات والدوائر الحكومية ويحق للسلطة في المنطقة الاستفادة من أي ميزة او اعفاء مقرر بموجب هذا القانون للمؤسسة المسجلة.\nب-تعتبر اموال السلطة اموالا عامة يتم تحصيلها وفقا لقانون تحصيل الاموال الاميرية الساري المفعول ويمارس الرئيس او من يفوضه لهذه الغاية جميع الصلاحيات المخولة بمقتضاه للحاكم الاداري ولجنة تحصيل الاموال الاميرية.","title":"إعفاءات السلطة وأموالها","memo":"⭐ تتمتع السلطة بإعفاءات وتسهيلات الوزارات والدوائر الحكومية، وبأي ميزة مقررة للمؤسسة المسجلة\n⭐ أموال السلطة أموال عامة تحصل وفق قانون تحصيل الأموال الأميرية\n⭐ يمارس الرئيس أو من يفوضه صلاحيات الحاكم الإداري ولجنة تحصيل الأموال الأميرية","qs":[{"q":"تحصل أموال السلطة وفقاً لـ:","o":["قانون تحصيل الأموال الأميرية","قانون التنفيذ","قانون ضريبة الدخل","قانون أصول المحاكمات المدنية"],"a":0},{"q":"لغايات تحصيل أموال السلطة، يمارس الرئيس أو من يفوضه الصلاحيات المخولة لـ:","o":["الحاكم الإداري ولجنة تحصيل الأموال الأميرية","وزير المالية","مدير دائرة ضريبة الدخل","رئيس التنفيذ"],"a":0}]},{"n":"22","chapter":"","notes":[],"source":"أ-على من يقوم بأي نشاط اقتصادي داخل المنطقة ويرغب في الاستفادة من أي من الميزات او الاعفاءات المقررة بموجب هذا القانون ان يتقدم إلى السلطة بطلب تسجيله مؤسسة مسجلة.\nب-تحدد اجراءات التسجيل وشروطه ورسوم التسجيل التي تستوفيها السلطة وأي امور اخرى تتعلق بذلك بمقتضى نظام يوضع لهذه الغاية.\nج-تعفى الشركة غير الاردنية المسجلة لدى السلطة من التسجيل لدى مراقب الشركات.\nد-مع مراعاة أحكام الفقرة (أ) من المادة (17) من هذا القانون يحظر على السلطة تملك الاسهم والحصص في المؤسسات المسجلة.\nه-تعامل جميع الوزارات والدوائر الحكومية والمؤسسات الرسمية والمؤسسات العامة في المنطقة معاملة المؤسسات المسجلة للاستفادة من التسهيلات والميزات المقررة لهذه المؤسسات وعلى اساس البيانات المتعلقة بحركة البضائع العائدة لأي من تلك الجهات التي يتوجب عليها تقديمها للسلطة.","title":"تسجيل المؤسسات","memo":"⭐ من يرغب بالاستفادة من الميزات والإعفاءات يتقدم للسلطة بطلب تسجيله مؤسسة مسجلة\n⭐ إجراءات التسجيل وشروطه ورسومه بنظام\n⭐ الشركة غير الأردنية المسجلة لدى السلطة معفاة من التسجيل لدى مراقب الشركات\n⭐ يحظر على السلطة تملك أسهم وحصص في المؤسسات المسجلة (مع مراعاة المادة 17/أ)","qs":[{"q":"تعفى الشركة غير الأردنية المسجلة لدى السلطة من:","o":["التسجيل لدى مراقب الشركات","ضريبة الدخل بشكل كامل","التسجيل لدى السلطة","تقديم البيانات المالية"],"a":0},{"q":"يحظر على السلطة، مع مراعاة أحكام المادة (17/أ):","o":["تملك الأسهم والحصص في المؤسسات المسجلة","تسجيل الشركات غير الأردنية","استيفاء رسوم التسجيل","التعاقد مع جهات مؤهلة فنياً ومالياً"],"a":0},{"q":"تحدد إجراءات تسجيل المؤسسات وشروطه ورسومه بمقتضى:","o":["نظام يوضع لهذه الغاية","تعليمات يصدرها رئيس المجلس","قرار من مجلس الوزراء","قانون الشركات"],"a":0}]},{"n":"23","chapter":"","notes":[],"source":"يحق لأي شخص غير مسجل كمؤسسة مسجلة ان يمارس نشاطا في المنطقة شريطة التقيد بالاسس والضوابط المحددة في هذا القانون والانظمة الصادرة بمقتضاه والمتعلقة بالمؤسسات المسجلة وأي شروط او اسس اخرى يقررها المجلس، ولا يحق له في هذه الحالة الاستفادة من الميزات او الاعفاءات المقررة للمؤسسات المسجلة بمقتضى هذا القانون.","title":"ممارسة النشاط دون تسجيل","memo":"⭐ يحق لغير المسجل ممارسة نشاط في المنطقة بشرط التقيد بالأسس والضوابط المتعلقة بالمؤسسات المسجلة وأي شروط يقررها المجلس\n⭐ لا يستفيد من الميزات أو الإعفاءات المقررة للمؤسسات المسجلة","qs":[{"q":"حالة عملية: تاجر يمارس نشاطاً في المنطقة دون أن يسجل كمؤسسة مسجلة، ما حكم نشاطه؟","o":["يجوز له ممارسة النشاط بالتقيد بالضوابط دون أن يستفيد من الميزات والإعفاءات","لا يجوز له ممارسة أي نشاط في المنطقة","يجوز له ويستفيد من نصف الإعفاءات المقررة","يجوز له بعد موافقة مجلس الوزراء ويستفيد من الإعفاءات كاملة"],"a":0},{"q":"يلتزم الشخص غير المسجل الذي يمارس نشاطاً في المنطقة بالأسس والضوابط المتعلقة بالمؤسسات المسجلة وبأي شروط أخرى يقررها:","o":["المجلس","مجلس الوزراء","وزير الصناعة والتجارة","مراقب الشركات"],"a":0}]},{"n":"24","chapter":"","notes":[],"source":"يسمح لأي مؤسسة ممارسة أي نشاط اقتصادي باستثناء ما يتم حظره او تقييد ممارسته في المنطقة بمقتضى نظام يوضع لهذه الغاية يتضمن الاسس والشروط اللازمة لممارسة النشاط المقيد وما يترتب عليه من عوائد للسلطة.","title":"الأنشطة الاقتصادية المسموحة","memo":"⭐ يسمح لأي مؤسسة بممارسة أي نشاط اقتصادي باستثناء ما يحظر أو يقيد بنظام\n⭐ النظام يتضمن أسس وشروط النشاط المقيد وعوائده للسلطة","qs":[{"q":"الأصل في ممارسة الأنشطة الاقتصادية في المنطقة أنه:","o":["يسمح بممارسة أي نشاط اقتصادي باستثناء ما يحظر أو يقيد بنظام","لا يسمح إلا بالأنشطة المحددة بقائمة يصدرها المجلس","يسمح بالأنشطة الصناعية والسياحية فقط","يحتاج كل نشاط لموافقة مجلس الوزراء"],"a":0},{"q":"تحظر الأنشطة الاقتصادية أو تقيد ممارستها في المنطقة بمقتضى:","o":["نظام يوضع لهذه الغاية","تعليمات يصدرها رئيس المجلس","قرار من رئيس الوزراء","اتفاق بين السلطة والمستثمر"],"a":0}]},{"n":"25","chapter":"","notes":[],"source":"أ-يسمح باستيراد البضائع إلى المنطقة وفقا لأحكام هذا القانون والانظمة والتعليمات الصادرة بمقتضاه.\nب-على كل من يستورد بضائع إلى المنطقة اتخاذ الاجراءات الكفيلة بعدم التصرف بها خلافا لأحكام هذا القانون والانظمة الصادرة بمقتضاه والتعليمات الصادرة بمقتضى أي منها.","title":"الاستيراد إلى المنطقة","memo":"⭐ يسمح باستيراد البضائع إلى المنطقة وفق القانون والأنظمة والتعليمات\n⭐ على المستورد اتخاذ الإجراءات الكفيلة بعدم التصرف بالبضائع خلافاً للقانون","qs":[{"q":"على كل من يستورد بضائع إلى المنطقة:","o":["اتخاذ الإجراءات الكفيلة بعدم التصرف بها خلافاً لأحكام القانون والأنظمة والتعليمات","الحصول على موافقة مجلس الوزراء المسبقة لكل شحنة","دفع الرسوم الجمركية عنها عند دخولها","تسجيلها لدى دائرة الجمارك العامة في عمان"],"a":0},{"q":"يسمح باستيراد البضائع إلى المنطقة وفقاً لـ:","o":["أحكام قانون المنطقة والأنظمة والتعليمات الصادرة بمقتضاه","أحكام قانون الجمارك حصراً","موافقة مسبقة من وزير الصناعة والتجارة","قرار يصدره مجلس الوزراء لكل شحنة"],"a":0}]},{"n":"26","chapter":"","notes":[],"source":"أ-يسمح للمؤسسات المسجلة بادخال البضائع إلى المنطقة ولا يجوز لغيرها ادخال البضائع إلى المنطقة الا وفقا لاسس وشروط تحدد بمقتضى تعليمات يصدرها مجلس الوزراء لهذه الغاية.\nب-يجوز للافراد ادخال امتعتهم الشخصية او المنزلية إلى المنطقة وتحدد انواع هذه الامتعة وكمياتها بمقتضى تعليمات خاصة يصدرها مجلس الوزراء لهذه الغاية.","title":"إدخال البضائع والأمتعة الشخصية","memo":"⭐ يسمح للمؤسسات المسجلة بإدخال البضائع، ولغيرها وفق تعليمات يصدرها مجلس الوزراء\n⭐ للأفراد إدخال أمتعتهم الشخصية أو المنزلية وتحدد أنواعها وكمياتها بتعليمات يصدرها مجلس الوزراء","qs":[{"q":"يجوز لغير المؤسسات المسجلة إدخال البضائع إلى المنطقة وفقاً لأسس وشروط تحدد بتعليمات يصدرها:","o":["مجلس الوزراء","مجلس المفوضين","رئيس المجلس","مدير عام الجمارك"],"a":0},{"q":"تحدد أنواع وكميات الأمتعة الشخصية أو المنزلية التي يجوز للأفراد إدخالها إلى المنطقة بمقتضى:","o":["تعليمات خاصة يصدرها مجلس الوزراء","نظام يصدر لهذه الغاية","قرار من رئيس المجلس","تعليمات يصدرها وزير المالية"],"a":0}]},{"n":"26 مكرر","chapter":"","notes":[],"source":"استثناء من أحكام المادتين (25) و (26) من هذا القانون يسمح بادخال او استيراد البضائع للجهات المبينة ادناه إلى المنطقة:\nأ-ما يرد باسم جلالة الملك المعظم.\nب-ما يرد للوزارات والدوائر الحكومية والمؤسسات الرسمية والمؤسسات العامة من هبات وتبرعات.\nج-ما يرد للقوات المسلحة والاجهزة الامنية الاردنية وما يرد لقوات عربية ترابط في المملكة من ذخائر واسلحة وتجهيزات والبسة عسكرية ووسائط نقل وقطعها واطارتها وأي مواد اخرى يقررها مجلس الوزراء بناء على تنسيب الرئيس.\nد-ما يرد للمؤسسة الاستهلاكية العسكرية او المؤسسة الاستهلاكية المدنية.\nه-ما يرد للاستعمال الشخصي إلى رؤساء واعضاء السلكين الدبلوماسي والقنصلي من غير المواطنين الاردنيين ، العاملين في المملكة وغير الفخريين الواردة اسماؤهم في الجداول التي تصدرها وزارة الخارجية وكذلك ما يرد إلى ازواجهم واولادهم القاصرين المقيمين معهم ، شريطة المعاملة بالمثل وبما يتناسب مع احتياجاتهم الفعلية.\nو- ما يرد للسفارات والمفوضيات والقنصليات غير الفخرية للاستعمال الرسمي باستثناء المواد الغذائية والمشروبات الروحية والتبغ وبما يتناسب مع احتياجاتهم الفعلية وضمن الحد المعقول ، وللرئيس عند الاقتضاء ان يعين الحد الاعلى لبعض انواع المستوردات بناء على اقتراح لجنة من ممثلين عن وزارة الخارجية والسلطة ، شريطة المعاملة بالمثل.\nز- ما يرد للاستعمال الشخصي ، مع التقيد باجراء المعاينة من امتعة شخصية واثاث وادوات منزلية للموظفين الاداريين العاملين في البعثات الدبلوماسية او القنصلية من حملة جنسية تلك البعثة الذين لا يستفيدون من الاعفاء المقرر ، شريطة المعاملة بالمثل وشريطة ان يتم الاستيراد خلال ستة اشهر من تاريخ وصول المستفيد من الاعفاء ويجوز تمديد هذه المدة لمدة مماثلة بموافقة وزارة الخارجية ، ولا يعتبر السائقون والخدم من الموظفين الاداريين لغايات تطبيق أحكام هذا البند.","title":"استثناءات إدخال واستيراد البضائع","memo":"⭐ يسمح استثناءً بإدخال ما يرد باسم جلالة الملك، وهبات الجهات الحكومية، ولوازم القوات المسلحة والأجهزة الأمنية، والمؤسستين الاستهلاكيتين العسكرية والمدنية\n⭐ السفارات: للاستعمال الرسمي باستثناء المواد الغذائية والمشروبات الروحية والتبغ، بشرط المعاملة بالمثل\n⭐ الموظفون الإداريون في البعثات: الاستيراد خلال 6 أشهر من الوصول قابلة للتمديد لمدة مماثلة بموافقة وزارة الخارجية\n⭐ السائقون والخدم لا يعتبرون موظفين إداريين","qs":[{"q":"يشترط لاستيراد الأمتعة الشخصية للموظفين الإداريين في البعثات الدبلوماسية أن يتم الاستيراد خلال:","o":["ستة أشهر من تاريخ وصول المستفيد قابلة للتمديد لمدة مماثلة بموافقة وزارة الخارجية","ثلاثة أشهر من تاريخ الوصول غير قابلة للتمديد","سنة من تاريخ الوصول قابلة للتمديد بموافقة الرئيس","ستة أشهر من تاريخ الوصول قابلة للتمديد بموافقة مجلس الوزراء"],"a":0},{"q":"يستثنى مما يرد للسفارات والقنصليات غير الفخرية للاستعمال الرسمي:","o":["المواد الغذائية والمشروبات الروحية والتبغ","الأثاث والأدوات المكتبية","وسائط النقل وقطعها","الأجهزة الإلكترونية"],"a":0},{"q":"أي من الفئات التالية لا تعتبر من الموظفين الإداريين لغايات تطبيق الاستثناء الوارد في المادة (26 مكرر)؟","o":["السائقون والخدم","الموظفون من حملة جنسية البعثة","المحاسبون العاملون في البعثة","السكرتيرون في البعثة"],"a":0},{"q":"المواد الأخرى التي ترد للقوات المسلحة والأجهزة الأمنية ويسمح بإدخالها استثناءً يقررها:","o":["مجلس الوزراء بناءً على تنسيب الرئيس","رئيس المجلس بناءً على تنسيب وزير الدفاع","مجلس المفوضين","رئيس هيئة الأركان المشتركة"],"a":0}]},{"n":"27","chapter":"","notes":[],"source":"أ-لمقاصد قانون الجمارك وقانون الضريبة العامة على المبيعات تعامل البضائع التي يتم ادخالها من قبل المؤسسة المسجلة إلى المنطقة من المنطقة الجمركية معاملة البضائع المصدرة او المعاد تصديرها.\nب-لمقاصد قانون الضريبة العامة على المبيعات تعامل الخدمات التي يتم بيعها إلى المؤسسة المسجلة في المنطقة من المنطقة الجمركية معاملة الخدمات المصدرة.\nج-يسمح بانتقال البضائع مدفوعة الرسوم والضرائب دون قيود من المنطقة الجمركية إلى المنطقة ، ولا تعتبر البضائع في هذه الحالة مصدرة او معاد تصديرها لمقاصد قانون الجمارك وقانون الضريبة العامة على المبيعات د. على الرغم من أي نص اخر ورد في هذا القانون تعامل البضائع المصنعة في المنطقة التي يتم اخراجها من المنطقة إلى المنطقة الجمركية معاملة المنتجات ذات المنشأ الاردني على ان تتوافر فيها قواعد المنشأ الاردني المعمول بها في المنطقة الجمركية.\nد-يعامل المسافرون المتجهون إلى المنطقة الجمركية عبر المراكز الجمركية القائمة على الحدود الفاصلة بين المنطقة والمنطقة الجمركية معاملة المسافر المقرر في قانون الجمارك النافذ المفعول.\nه-تقوم المراكز الجمركية القائمة على الحدود الفاصلة بين المنطقة والمنطقة الجمركية بمهامها وتمارس صلاحياتها وفقا لأحكام قانون الجمارك النافذ المفعول وهذا القانون كل حسب اختصاصه.","title":"معاملة البضائع والخدمات بين المنطقة والمنطقة الجمركية","memo":"⭐ البضائع التي تدخلها المؤسسة المسجلة من المنطقة الجمركية تعامل معاملة البضائع المصدرة أو المعاد تصديرها (الجمارك والمبيعات)\n⭐ الخدمات المبيعة للمؤسسة المسجلة من المنطقة الجمركية تعامل معاملة الخدمات المصدرة (المبيعات)\n⭐ البضائع مدفوعة الرسوم تنتقل دون قيود ولا تعتبر مصدرة\n⭐ البضائع المصنعة في المنطقة المخرجة للمنطقة الجمركية تعامل كمنتجات أردنية المنشأ إذا توافرت قواعد المنشأ","qs":[{"q":"لمقاصد قانون الضريبة العامة على المبيعات، تعامل الخدمات المبيعة إلى المؤسسة المسجلة في المنطقة من المنطقة الجمركية معاملة:","o":["الخدمات المصدرة","الخدمات المحلية الخاضعة للضريبة","الخدمات المستوردة","الخدمات المعفاة إعفاءً جزئياً"],"a":0},{"q":"حالة عملية: نقل تاجر بضائع مدفوعة الرسوم والضرائب من عمان إلى المنطقة. كيف تعامل هذه البضائع؟","o":["تنتقل دون قيود ولا تعتبر مصدرة أو معاد تصديرها","تعامل معاملة البضائع المصدرة ويسترد الرسوم","تعامل معاملة البضائع المستوردة إلى المنطقة","تخضع لرسوم إضافية لصالح السلطة"],"a":0},{"q":"تعامل البضائع المصنعة في المنطقة عند إخراجها إلى المنطقة الجمركية معاملة المنتجات ذات المنشأ الأردني بشرط:","o":["أن تتوافر فيها قواعد المنشأ الأردني المعمول بها في المنطقة الجمركية","أن تكون مدخلاتها جميعها أردنية","أن توافق عليها وزارة الصناعة والتجارة","أن تصنعها مؤسسة مسجلة أردنية الجنسية"],"a":0}]},{"n":"28","chapter":"","notes":[],"source":"لمجلس الوزراء بناء على تنسيب وزير المالية المستند إلى طلب المجلس اعفاء البضائع من منشا المنطقة من الرسوم الجمركية جزئيا عند وضعها في الاستهلاك المحلي في المنطقة الجمركية وفقا للحالات والشروط التالية:\nأ-إذا كانت مستلزمات انتاج البضاعة والجدوى الاقتصادية لا تتوفر الا في المنطقة.\nب-ان يكون الاعفاء في حدود قيمة المواد والتكاليف والنفقات المحلية الداخلة في الانتاج داخل المنطقة بحيث يتم استيفاء جميع الرسوم الجمركية والرسوم والضرائب الاخرى المتوجبة على مدخلات الانتاج الاجنبية وفقا للتشريعات ذات العلاقة المعمول بها في المنطقة الجمركية.\nج-ان تتوافر في البضاعة المنتجة قواعد المنشا الواردة في قانون الجمارك النافذ المفعول.","title":"الإعفاء الجزئي لبضائع منشأ المنطقة","memo":"⭐ لمجلس الوزراء بتنسيب وزير المالية المستند إلى طلب المجلس إعفاء بضائع منشأ المنطقة جزئياً من الرسوم الجمركية عند وضعها في الاستهلاك المحلي\n⭐ الشروط: مستلزمات الإنتاج والجدوى لا تتوفر إلا في المنطقة؛ الإعفاء في حدود قيمة المواد والتكاليف المحلية؛ توافر قواعد المنشأ في قانون الجمارك\n⭐ تستوفى الرسوم كاملة على مدخلات الإنتاج الأجنبية","qs":[{"q":"الجهة المختصة بإعفاء البضائع من منشأ المنطقة جزئياً من الرسوم الجمركية عند وضعها في الاستهلاك المحلي هي:","o":["مجلس الوزراء بتنسيب وزير المالية المستند إلى طلب المجلس","مجلس المفوضين بموافقة وزير المالية","وزير المالية بتنسيب مدير عام الجمارك","رئيس الوزراء بتنسيب رئيس المجلس"],"a":0},{"q":"يكون الإعفاء الجزئي لبضائع منشأ المنطقة في حدود:","o":["قيمة المواد والتكاليف والنفقات المحلية الداخلة في الإنتاج داخل المنطقة","قيمة مدخلات الإنتاج الأجنبية","50% من الرسوم الجمركية المستحقة","القيمة التي يحددها مجلس المفوضين"],"a":0},{"q":"أي مما يلي ليس من شروط الإعفاء الجزئي لبضائع منشأ المنطقة؟","o":["أن تكون المؤسسة المنتجة مملوكة بالكامل لأردنيين","أن تكون مستلزمات الإنتاج والجدوى الاقتصادية لا تتوفر إلا في المنطقة","أن تتوافر في البضاعة قواعد المنشأ الواردة في قانون الجمارك","أن يكون الإعفاء في حدود قيمة المواد والتكاليف المحلية"],"a":0}]},{"n":"29","chapter":"","notes":[],"source":"أ-تعتبر المنطقة خارج حدود المنطقة الجمركية ولا تسري عليها أحكام التشريعات الجمركية الا وفق ما ورد عليه نص في هذا القانون.\nب-تتولى السلطة داخل حدود المنطقة صلاحيات جمركية بمقتضى نظام يوضع لهذه الغاية تتناول احكامه بصورة خاصة ما يلي:\n1-مكافحة التهريب والانشطة التجارية غير المشروعة.\n2-اصدار التعليمات الخاصة بالاستيراد إلى المنطقة والتصدير منها.\n3-اعداد البيانات والمعلومات الاحصائية المتعلقة بعمليات الاستيراد والتصدير.","title":"الوضع الجمركي للمنطقة","memo":"⭐ المنطقة خارج حدود المنطقة الجمركية ولا تسري عليها التشريعات الجمركية إلا بنص في هذا القانون\n⭐ تتولى السلطة صلاحيات جمركية بنظام: مكافحة التهريب، تعليمات الاستيراد والتصدير، الإحصاءات","qs":[{"q":"تعتبر منطقة العقبة الاقتصادية الخاصة من الناحية الجمركية:","o":["خارج حدود المنطقة الجمركية ولا تسري عليها التشريعات الجمركية إلا بنص في قانونها","جزءاً من المنطقة الجمركية","منطقة حرة تابعة لمؤسسة المناطق الحرة","خاضعة لقانون الجمارك بشكل كامل"],"a":0},{"q":"تتولى السلطة صلاحياتها الجمركية داخل المنطقة بمقتضى:","o":["نظام يوضع لهذه الغاية","قانون الجمارك مباشرة","تعليمات يصدرها مدير عام الجمارك","قرار من وزير المالية"],"a":0}]},{"n":"30","chapter":"","notes":[],"source":"أ-لا تستوفى في المنطقة الرسوم والضرائب التالية:\n1-الرسوم الجمركية ورسوم الاستيراد والرسوم والضرائب الاخرى على المستوردات إليها.\n2-الضريبة العامة على المبيعات او أي ضريبة تحل محلها على المستوردات إلى المنطقة او المبيعات فيها من السلع والخدمات.\nب-مع مراعاة ما ورد عليه نص في هذا القانون تعفى المؤسسة المسجلة ومن تاريخ تسجيلها من جميع الضرائب والرسوم بما في ذلك ما يلي:\n1-ضريبة الدخل وضريبة الخدمات الاجتماعية وضريبة توزيع ارباح الاسهم والحصص في الشركات عن الدخل المتحقق للمؤسسة المسجلة عن نشاطها في المنطقة او خارج المملكة.\n2-ضريبة الابنية والاراضي على ما يلزمها من ابنية واراض لممارسة نشاطها.\nج-لا يشمل الاعفاء المنصوص عليه في هذه المادة ما يلي:\n1-الرسوم وبدلات الخدمات التي تستوفيها الجهات الحكومية الاخرى من دوائر الحكومة مقابل الخدمات التي تخرج عن مهمات وصلاحيات ومسؤوليات السلطة.\n2-ضريبة بيع الاراضي والعقارات وانتقالها، وتحصل لصالح الخزينة.\n3-أي ضرائب او رسوم ينص هذا القانون على فرضها او استيفائها.\n4-الضرائب والرسوم المفروضة على المركبات.\nد-بالرغم مما ورد في الفقرة (ج) من هذه المادة يجوز اعفاء المركبات المستخدمة من قبل المؤسسة المسجلة من الرسوم الجمركية والضريبة العامة على المبيعات تحت وضع الادخال المؤقت وذلك بموجب نظام يصدره مجلس الوزراء.","title":"الرسوم والضرائب غير المستوفاة والإعفاءات","memo":"⭐ لا تستوفى في المنطقة الرسوم الجمركية ورسوم الاستيراد، ولا ضريبة المبيعات على المستوردات أو المبيعات فيها\n⭐ تعفى المؤسسة المسجلة من تاريخ تسجيلها من ضريبة الخدمات الاجتماعية وتوزيع الأرباح وضريبة الأبنية والأراضي\n⭐ لا يشمل الإعفاء: ضريبة بيع الأراضي والعقارات (للخزينة)، ضرائب ورسوم المركبات، رسوم الجهات الحكومية الأخرى\n⭐ يجوز إعفاء مركبات المؤسسة المسجلة تحت وضع الإدخال المؤقت بنظام من مجلس الوزراء","qs":[{"q":"تعفى المؤسسة المسجلة من الضرائب والرسوم المنصوص عليها في المادة (30) اعتباراً من:","o":["تاريخ تسجيلها","تاريخ بدء الإنتاج الفعلي","تاريخ بدء العمل في المنطقة","بداية السنة المالية التالية لتسجيلها"],"a":0},{"q":"أي مما يلي لا يشمله إعفاء المؤسسة المسجلة؟","o":["ضريبة بيع الأراضي والعقارات وانتقالها","ضريبة الأبنية والأراضي على ما يلزمها لممارسة نشاطها","ضريبة توزيع أرباح الأسهم والحصص","الضريبة العامة على المبيعات على مبيعاتها في المنطقة"],"a":0},{"q":"تحصل ضريبة بيع الأراضي والعقارات وانتقالها في المنطقة لصالح:","o":["الخزينة","السلطة","بلدية العقبة","صندوق تنمية الإقليم"],"a":0},{"q":"يجوز إعفاء المركبات المستخدمة من قبل المؤسسة المسجلة من الرسوم الجمركية والضريبة العامة على المبيعات:","o":["تحت وضع الإدخال المؤقت بموجب نظام يصدره مجلس الوزراء","إعفاءً دائماً بقرار من مجلس المفوضين","بموافقة وزير المالية لمدة سنة","لا يجوز إعفاؤها مطلقاً"],"a":0}]},{"n":"31","chapter":"","notes":[],"source":"إذا كانت المؤسسات المسجلة او الاستثمارات او الانشطة القائمة في المنطقة عند نفاذ هذا القانون تتمتع بموجب أي تشريع اخر او اتفاق خاص بميزات او اعفاءات تشكل افضلية لها عما هو مقرر في هذا القانون فتستمر في الاستفادة من هذه الميزات او الاعفاءات لحين انتهاء المدة المقررة لها.","title":"استمرار الميزات الأفضل","memo":"⭐ المؤسسات والاستثمارات القائمة عند نفاذ القانون التي تتمتع بميزات أو إعفاءات أفضل بموجب تشريع آخر أو اتفاق خاص تستمر بالاستفادة منها لحين انتهاء مدتها","qs":[{"q":"حالة عملية: استثمار قائم في العقبة عند نفاذ القانون يتمتع بموجب اتفاق خاص بإعفاءات أفضل مما يقرره قانون المنطقة. ما الحكم؟","o":["يستمر في الاستفادة من تلك الإعفاءات لحين انتهاء المدة المقررة لها","تلغى إعفاءاته ويخضع لأحكام قانون المنطقة فوراً","يخير بين الإعفاءين خلال سنة","يستمر بها لمدة سنتين فقط من نفاذ القانون"],"a":0},{"q":"يستمر انتفاع المؤسسات القائمة بالميزات الأفضل المقررة بموجب تشريع آخر أو اتفاق خاص:","o":["لحين انتهاء المدة المقررة لها","مدى الحياة","لحين صدور نظام يلغيها","لمدة خمس سنوات من نفاذ القانون"],"a":0}]},{"n":"32","chapter":"","notes":[],"source":"أ-يخضع دخل المؤسسة المسجلة المتأتي من نشاطها في المنطقة او المتأتي مباشرة عن هذا النشاط خارج المملكة لضريبة دخل تعادل ( %5) من مجموع دخلها ويتم تحديد هذا الدخل وتحديد اسس احتسابه وسائر الامور المتعلقة به بمقتضى نظام يصدر لهذه الغاية.\nب-على الرغم مما ورد في الفقرة (أ) من هذه المادة يخضع الدخل المتاتي للبنوك والمؤسسات المالية وشركات التامين واعادة التامين وشركات النقل البري العاملة في المنطقة سواء كانت مؤسسة مسجلة او غير مسجلة لأحكام قانون ضريبة الدخل المعمول به.\nج-يخضع دخل أي شخص من غير المؤسسات المسجلة المتاتي من عمله في المنطقة لضريبة الدخل وفقا لأحكام قانون ضريبة الدخل بما في ذلك ما يتقاضاه أي شخص طبيعي من رواتب واجور وعلاوات ومكافات وما ماثلها كما يخضع هذا الدخل إلى ضريبة المبيعات الاجتماعية وفقا لأحكام قانون ضريبة الخدمات الاجتماعية.\nد-إذا كان الدخل المنصوص عليه في الفقرة (ج) من هذه المادة يتأتى بصورة مشتركة من المنطقة والمنطقة الجمركية تقوم السلطة او دائرة ضريبة الدخل ، حسب مقتضى الحال ، بتقدير وتحصيل ضريبة الدخل وضريبة الخدمات الاجتماعية من هؤلاء الاشخاص ويتم تحديد اسس التقدير والتحصيل واجراءات تقديم كشوف التقدير الذاتي وأي اجراءات اخرى ذات علاقة بمقتضى نظام يصدر لهذه الغاية.\nه-تطبق الاعفاءات المنصوص عليها في قانون ضريبة الدخل النافذ المفعول على أي دخل يتأتى في المنطقة للجهات المستفيدة من تلك الاعفاءات.\nو- يعفى من ضريبة الدخل المنصوص عليها في الفقرة (أ) من هذه المادة ما يلي:\n1-الارباح الرأسمالية التي ترد للمؤسسة المسجلة بما في ذلك الارباح الناجمة عن شراء الاراضي والعقارات والاسهم والسندات وبيعها باستثناء ارباح بيع او نقل ملكية الاصول المشمولة بأحكام الاستهلاك المنصوص عليها بموجب قانون ضريبة الدخل النافذ المفعول على ان يجري تنزيل الخسائر الناجمة عن بيع او نقل ملكية هذه الاصول في حال تحققها وتحدد هذه الخسائر بما يعادل مبلغ الاستهلاك الذي يتم تنزيله وفقا لأحكام قانون ضريبة الدخل.\n2-الدخل الذي يتأتى من الارض المستثمرة في الزراعة او البستنة او التحريج او من تربية الماشية او الدواجن او الاسماك او النحل بما في ذلك الدخل الناجم عن تحويل منتوجاتها إلى سلع اخرى بطريق العمل اليدوي البسيط.\n3-الدخل الناجم عن امتياز منحته الحكومة او اتفاق عقدته واعفي صراحة من الضريبة بموجب شروط ذلك الامتياز او الاتفاق.","title":"ضريبة الدخل في المنطقة","memo":"⭐ دخل المؤسسة المسجلة من نشاطها في المنطقة أو المتأتي مباشرة عنه خارج المملكة: ضريبة 5% من مجموع دخلها\n⭐ البنوك والمؤسسات المالية والتأمين وإعادة التأمين والنقل البري: تخضع لقانون ضريبة الدخل (مسجلة أو غير مسجلة)\n⭐ دخل غير المؤسسات المسجلة والرواتب والأجور: قانون ضريبة الدخل\n⭐ يعفى من نسبة 5%: الأرباح الرأسمالية (عدا الأصول القابلة للاستهلاك)، الدخل الزراعي، دخل الامتياز المعفى صراحة","qs":[{"q":"يخضع دخل المؤسسة المسجلة المتأتي من نشاطها في المنطقة لضريبة دخل تعادل:","o":["5% من مجموع دخلها","10% من مجموع دخلها","5% من صافي دخلها الخاضع للضريبة","20% من مجموع دخلها"],"a":0},{"q":"أي من الجهات التالية العاملة في المنطقة يخضع دخلها لأحكام قانون ضريبة الدخل المعمول به وليس لنسبة الـ 5%؟","o":["شركات النقل البري","المصانع المسجلة","الفنادق المسجلة","شركات التجارة المسجلة"],"a":0},{"q":"حالة عملية: باعت مؤسسة مسجلة آلات مشمولة بأحكام الاستهلاك بربح، وباعت أسهماً بربح آخر. ما المعاملة الضريبية وفق المادة (32)؟","o":["ربح الأسهم معفى، وربح بيع الآلات غير معفى","الربحان معفيان من الضريبة","الربحان خاضعان لضريبة 5%","ربح الآلات معفى، وربح الأسهم خاضع"],"a":0},{"q":"أي مما يلي ليس من الدخل المعفى من ضريبة الدخل المنصوص عليها في المادة (32/أ)؟","o":["الدخل المتأتي من تقديم الخدمات الفندقية في المنطقة","الدخل المتأتي من الأرض المستثمرة في الزراعة أو تربية الماشية","الأرباح الرأسمالية الناجمة عن بيع الأراضي والعقارات","الدخل الناجم عن امتياز منحته الحكومة وأعفي صراحة من الضريبة"],"a":0}]},{"n":"33","chapter":"","notes":[],"source":"مع مراعاة أحكام قانون ضريبة الدخل وقانون ضريبة الخدمات الاجتماعية والانظمة والتعليمات الصادرة بمقتضى أي منهما يلتزم كل شخص او\nكل مؤسسة مسجلة او مستثمر في المنطقة بما يلي:\nأ-خصم ضريبة الدخل وضريبة الخدمات الاجتماعية المتحققة على ما يدفعه لأي شخص طبيعي من رواتب او اجور او علاوات او مكافات او مخصصات وتوريدها للسلطة.\nب-خصم ما نسبته (%10) من أي مبلغ من دخل غير معفى من الضريبة يدفعه لشخص غير مقيم وذلك باستثناء ما تدفعه المؤسسة المسجلة للمستثمر الذي يساهم في راسمالها بنسبة لا تقل عن (%20) وتوريدها للسلطة.","title":"التزامات الخصم والتوريد","memo":"⭐ خصم ضريبة الدخل وضريبة الخدمات الاجتماعية على الرواتب والأجور والمكافآت وتوريدها للسلطة\n⭐ خصم 10% من أي دخل غير معفى يدفع لشخص غير مقيم وتوريده للسلطة\n⭐ يستثنى ما تدفعه المؤسسة المسجلة لمستثمر يساهم في رأسمالها بنسبة لا تقل عن 20%","qs":[{"q":"نسبة الخصم على أي مبلغ من دخل غير معفى يدفع لشخص غير مقيم في المنطقة هي:","o":["10%","5%","20%","15%"],"a":0},{"q":"يستثنى من الخصم على المبالغ المدفوعة لغير المقيم ما تدفعه المؤسسة المسجلة للمستثمر الذي يساهم في رأسمالها بنسبة لا تقل عن:","o":["20%","10%","25%","50%"],"a":0},{"q":"توُرَّد المبالغ المخصومة من رواتب وأجور الأشخاص الطبيعيين العاملين في المنطقة إلى:","o":["السلطة","دائرة ضريبة الدخل والمبيعات","وزارة المالية","المؤسسة العامة للضمان الاجتماعي"],"a":0}]},{"n":"34","chapter":"","notes":[],"source":"أ-تتولى السلطة صلاحيات تقدير ضريبة الدخل في المنطقة وتحصيلها وفقا لأحكام هذا القانون وقانون ضريبة الدخل المعمول به والانظمة والتعليمات الصادرة بمقتضاه، ولهذه الغاية يخول الرئيس، حسب مقتضى الحال، الصلاحيات المقررة للوزير والمدير العام في تلك التشريعات.\nب-على الرغم مما ورد في الفقرة (أ) من هذه المادة ، تستمر دائرة ضريبة الدخل في تقدير وتحصيل ضريبة الدخل وضريبة الخدمات الاجتماعية وأي مبالغ اخرى مستحقة لها على المكلفين في المنطقة قبل نفاذ أحكام هذا القانون ومتابعة جميع الاجراءات القضائية والقانونية المتعلقة بها وفق أحكام التشريعات الضريبية النافذة في المنطقة الجمركية.","title":"صلاحيات تقدير ضريبة الدخل وتحصيلها في المنطقة","memo":"⭐ تتولى السلطة تقدير ضريبة الدخل في المنطقة وتحصيلها وفق هذا القانون وقانون ضريبة الدخل\n⭐ يُخوَّل الرئيس صلاحيات الوزير والمدير العام المقررة في تشريعات ضريبة الدخل\n⭐ تستمر دائرة ضريبة الدخل في تقدير وتحصيل الضرائب المستحقة على المكلفين في المنطقة عن الفترة السابقة لنفاذ هذا القانون ومتابعة إجراءاتها القضائية","qs":[{"q":"الجهة التي تتولى صلاحيات تقدير ضريبة الدخل في المنطقة وتحصيلها وفقاً لقانون منطقة العقبة الاقتصادية الخاصة هي:","o":["سلطة منطقة العقبة الاقتصادية الخاصة","دائرة ضريبة الدخل والمبيعات","وزارة المالية","دائرة الجمارك العامة"],"a":0},{"q":"لغايات تقدير ضريبة الدخل في المنطقة يُخوَّل الرئيس الصلاحيات المقررة لـ:","o":["الوزير والمدير العام في تشريعات ضريبة الدخل","مجلس الوزراء ووزير المالية","محكمة استئناف قضايا ضريبة الدخل","المجلس القضائي"],"a":0},{"q":"حالة عملية: مكلف في المنطقة ترتبت عليه ضريبة دخل عن فترة سابقة لنفاذ قانون المنطقة، فإن الجهة التي تستمر في تقديرها وتحصيلها هي:","o":["دائرة ضريبة الدخل وفق التشريعات الضريبية النافذة في المنطقة الجمركية","سلطة المنطقة وفق أحكام قانون المنطقة","رئيس السلطة بقرار منه","مجلس المفوضين بتنسيب من وزير المالية"],"a":0}]},{"n":"35","chapter":"","notes":[],"source":"إذا تبين للسلطة او لدائرة ضريبة الدخل ان المؤسسة المسجلة تقوم بالتعامل مع اشخاص في المنطقة الجمركية تربطهم بها منفعة مالية مشتركة مما يخرج عن نطاق التعامل المالوف بين اشخاص غير مرتبطين بمصالح مشتركة وذلك بقصد تخفيف العبء الضريبي المتحقق على أي منهم فيحق للسلطة او الدائرة حسب مقتضى الحال، تقدير الدخل على المؤسسة او الشخص ذي العلاقة دون اعتبار لهذا التعامل.","title":"التعامل مع أشخاص ذوي مصلحة مشتركة","memo":"⭐ إذا تعاملت المؤسسة المسجلة مع أشخاص في المنطقة الجمركية تربطهم بها منفعة مالية مشتركة خارج نطاق التعامل المألوف بقصد تخفيف العبء الضريبي\n⭐ يحق للسلطة أو دائرة ضريبة الدخل تقدير الدخل دون اعتبار لهذا التعامل","qs":[{"q":"إذا تبين أن المؤسسة المسجلة تتعامل مع أشخاص في المنطقة الجمركية تربطهم بها منفعة مالية مشتركة بقصد تخفيف العبء الضريبي، فإن للسلطة أو الدائرة:","o":["تقدير الدخل على المؤسسة أو الشخص ذي العلاقة دون اعتبار لهذا التعامل","إلغاء تسجيل المؤسسة فوراً","فرض غرامة تعادل مثلي الضريبة","إحالة المؤسسة إلى محكمة الجمارك البدائية"],"a":0},{"q":"الشرط الذي يجيز إهمال التعامل بين المؤسسة المسجلة والأشخاص المرتبطين بها عند تقدير الدخل هو أن يكون التعامل:","o":["خارجاً عن نطاق التعامل المألوف بين أشخاص غير مرتبطين وبقصد تخفيف العبء الضريبي","بالعملة الأجنبية","مع أشخاص خارج المملكة","غير موثق بعقود مكتوبة"],"a":0}]},{"n":"36","chapter":"","notes":[],"source":"أ-على السلطة تزويد دائرة ضريبة الدخل بالكشوف والبيانات المتعلقة بأي دخل خاضع للضريبة تقوم بتحصيله بموجب أحكام هذا القانون.\nب-يحق لمدير عام دائرة ضريبة الدخل او من يفوضه، إذا اقتضت المصلحة، الإطلاع على السجلات والوثائق المتعلقة بضريبة الدخل المتاتية والمتحققة في المنطقة وفقا لأحكام هذا القانون.","title":"تبادل المعلومات مع دائرة ضريبة الدخل","memo":"⭐ على السلطة تزويد دائرة ضريبة الدخل بالكشوف والبيانات المتعلقة بأي دخل خاضع للضريبة تحصّله\n⭐ لمدير عام دائرة ضريبة الدخل أو من يفوضه، إذا اقتضت المصلحة، الاطلاع على سجلات ووثائق ضريبة الدخل المتحققة في المنطقة","qs":[{"q":"الجهة الملزمة بتزويد دائرة ضريبة الدخل بالكشوف والبيانات المتعلقة بالدخل الخاضع للضريبة الذي يتم تحصيله في المنطقة هي:","o":["السلطة","المؤسسة المسجلة مباشرة","وزارة المالية","البنك المركزي"],"a":0},{"q":"يحق الاطلاع على السجلات والوثائق المتعلقة بضريبة الدخل المتحققة في المنطقة، إذا اقتضت المصلحة، لـ:","o":["مدير عام دائرة ضريبة الدخل أو من يفوضه","وزير المالية فقط","رئيس ديوان المحاسبة","مجلس الوزراء"],"a":0}]},{"n":"37","chapter":"","notes":[],"source":"أ-على الرغم مما ورد في المادة (30) من هذا القانون، تفرض ضريبة مبيعات على السلع المباعة والخدمات المؤداة في المنطقة على النحو التالي:\n1-ضريبة بنسبة (%7) من قيمة بيع سلع وخدمات يتم تحديدها بموجب نظام عند بيعها للاستهلاك في المنطقة على ان يتضمن هذا النظام الأحكام والاجراءات المتعلقة بتحصيل الضريبة وردها.\n2-ضريبة على مبيعات السلع المحلية منشأ المنطقة من المنطقة إلى المنطقة الجمركية وفق أحكام قانون الضريبة العامة على المبيعات المعمول به على ان يبرز للمركز الجمركي ما يؤكد دفع الضريبة وذلك دون الخضوع لاجراءات تنظيم بيان جمركي في المنطقة الجمركية.\n3-ضريبة على مبيعات الخدمات من المنطقة إلى باقي مناطق المملكة او إلى خارجها وفقا لأحكام قانون الضريبة العامة على المبيعات النافذ المفعول.\nب-يستوفي بائع السلعة او الخدمة الضريبة المنصوص عليها في الفقرة (أ) من هذه المادة ويوردها للسلطة.\nج-يفرض مجلس الوزراء ضريبة خاصة على مبيعات التبغ ومصنوعاته والمشروبات الكحولية والمسكرات والجعة عند بيعها للاستهلاك في المنطقة وفق تعليمات يصدرها لهذه الغاية.\nد-لمقاصد هذه المادة تمارس السلطة صلاحيات دائرة الضريبة العامة على المبيعات كما يمارس الرئيس ، حسب مقتضى الحال ، صلاحيات الوزير والمدير العام المنصوص عليها في قانون الضريبة العامة على المبيعات.","title":"ضريبة المبيعات في المنطقة","memo":"⭐ ضريبة بنسبة (7%) على سلع وخدمات يحددها نظام عند بيعها للاستهلاك في المنطقة\n⭐ مبيعات السلع المحلية منشأ المنطقة إلى المنطقة الجمركية تخضع لقانون الضريبة العامة على المبيعات دون تنظيم بيان جمركي\n⭐ يستوفي البائع الضريبة ويوردها للسلطة؛ ومجلس الوزراء يفرض ضريبة خاصة على التبغ والمشروبات الكحولية\n⭐ يمارس الرئيس صلاحيات الوزير والمدير العام في قانون الضريبة العامة على المبيعات","qs":[{"q":"نسبة ضريبة المبيعات المفروضة على السلع والخدمات المحددة بنظام عند بيعها للاستهلاك في المنطقة:","o":["(7%)","(16%)","(5%)","(10%)"],"a":0},{"q":"الجهة التي تفرض ضريبة خاصة على مبيعات التبغ ومصنوعاته والمشروبات الكحولية عند بيعها للاستهلاك في المنطقة:","o":["مجلس الوزراء","مجلس المفوضين","رئيس السلطة","وزير المالية"],"a":0},{"q":"يستوفي ضريبة المبيعات المنصوص عليها في الفقرة (أ) ويوردها للسلطة:","o":["بائع السلعة أو الخدمة","مشتري السلعة أو الخدمة","المركز الجمركي","دائرة الضريبة العامة على المبيعات"],"a":0},{"q":"بيع سلع محلية منشأ المنطقة من المنطقة إلى المنطقة الجمركية يخضع لضريبة وفق قانون الضريبة العامة على المبيعات على أن:","o":["يُبرز للمركز الجمركي ما يؤكد دفع الضريبة دون الخضوع لإجراءات تنظيم بيان جمركي","يُنظم بيان جمركي كامل في المنطقة الجمركية","تُستوفى الضريبة بنسبة (7%) فقط","يُعفى من الضريبة إذا كان البيع لمؤسسة مسجلة"],"a":0}]},{"n":"37 مكرر","chapter":"","notes":[],"source":"يعفى من الضريبة المنصوص عليها في البند (1) من الفقرة (أ) ومن الضريبة المنصوص عليها في الفقرة (ج) من المادة (37) من هذا القانون ، حسب مقتضى الحال ، ما يلي:\nأ-مشتريات ومستوردات جلالة الملك المعظم من السلع والخدمات.\nب-السلع والخدمات المبينة ادناه ، حسبما تقتضي الاتفاقيات والبروتوكولات الدولية شريطة المعاملة بالمثل:\n1-السلع والخدمات التي تشتريها من المنطقة السفارات والمفوضيات والقنصليات غير الفخرية لاستعمالها الخاص.\n2-السلع والخدمات التي يشتريها من المنطقة اعضاء السلكين الدبلوماسي والقنصلي المعتمدين لدى المملكة شريطة ان يكونوا غير اردنيين وغير فخريين.\n3-السلع والخدمات التي تشتريها من المنطقة المنظمات الدولية والاقليمية العاملة في المملكة وموظفوها غير الاردنيين الذي يتمتعون بالصفة الدبلوماسية.\nج-يتم اعفاء السلع والخدمات الواردة في الفقرة (ب) من هذه المادة وتحديد كمياتها بقرار من الرئيس بناء على تنسيب من وزير الخارجية.","title":"الإعفاءات من ضريبة المبيعات في المنطقة","memo":"⭐ يعفى من ضريبة (7%) والضريبة الخاصة: مشتريات ومستوردات جلالة الملك\n⭐ يعفى بشرط المعاملة بالمثل: السفارات والقنصليات غير الفخرية، والدبلوماسيون غير الأردنيين وغير الفخريين، والمنظمات الدولية وموظفوها غير الأردنيين\n⭐ الإعفاء وتحديد الكميات بقرار من الرئيس بناءً على تنسيب وزير الخارجية","qs":[{"q":"يتم إعفاء السلع والخدمات التي تشتريها السفارات والمنظمات الدولية وتحديد كمياتها بقرار من:","o":["الرئيس بناءً على تنسيب من وزير الخارجية","وزير الخارجية بناءً على تنسيب من الرئيس","مجلس الوزراء بناءً على تنسيب من المجلس","وزير المالية"],"a":0},{"q":"شرط إعفاء السلع والخدمات التي يشتريها أعضاء السلكين الدبلوماسي والقنصلي من المنطقة:","o":["أن يكونوا غير أردنيين وغير فخريين مع المعاملة بالمثل","أن يكونوا مقيمين في المنطقة","ألا تتجاوز قيمة المشتريات ألف دينار","أن تكون المشتريات للاستعمال التجاري"],"a":0},{"q":"أي مما يلي لا يُعفى من ضريبة المبيعات المنصوص عليها في البند (1) من الفقرة (أ) من المادة (37) وفق النص؟","o":["مشتريات القنصليات الفخرية","مشتريات ومستوردات جلالة الملك","مشتريات السفارات لاستعمالها الخاص","مشتريات المنظمات الدولية العاملة في المملكة"],"a":0}]},{"n":"38","chapter":"","notes":[],"source":"مع مراعاة أحكام قانون ضريبة الدخل وقانون الضريبة العامة على المبيعات والانظمة والتعليمات الصادرة بمقتضى أي منهما:\nأ-تختص محكمة استئناف قضايا ضريبة الدخل بالنظر في الاستئنافات المقدمة للطعن في قرارات تقدير الضريبة على الدخل واعادة النظر في التقدير الذي تم وفقا لأحكام هذا القانون كما تختص بالنظر في المطالبات المتعلقة بالغرامات والمبالغ الاضافية المتحققة وفقا لاحكامه والنظر في أي مبالغ يتوجب خصمها او دفعها او اقتطاعها كضريبة نهائية او كدفعة على حساب الضريبة.\nب-تختص محكمة الجمارك البدائية بالنظر في الدعاوى التالية ، كما تختص محكمة الجمارك الاستئنافية بالنظر في الاستئنافات المقدمة بهذا الشأن:\n1-الجمارك والمخالفات الجمركية التي ترتكب خلافا لأحكام هذا القانون والانظمة الصادرة بمقتضاه.\n2-الجرائم التي ترتكب خلافا لأحكام النظام المشار إليها في البند (1) من الفقرة (أ) من المادة (37) من هذا القانون وتعليمات الاستيراد والتصدير.\n3-الطعن في القرارات المتعلقة بتحديد المبالغ الخاضعة لضريبة المبيعات وفقا لأحكام هذا القانون.\n4-توقيف الاشخاص المتهمين بارتكاب الجرائم المنصوص عليها في البندين (1) و(2) من هذه الفقرة واخلاء سبيلهم وفي الحالات التي لم تكن القضية قد وردت إلى المحكمة بعد يجوز لرئيس المحكمة ان يطلب من الشخص الذي اسندت اليه تهمة تقديم كفالة نقدية او عدلية لضمان حضوره للمحكمة والا يقرر توقيفه لحين صدور حكم قطعي من المحكمة المختصة او تقديم تلك الكفالة.\n5-الافراج عن البضائع المحجوزة في القضايا المنظورة لديها لقاء كفالة مصرفية او نقدية تعادل قيمة هذه البضائع والافراج عن وسائط النقل المحجوزة بعد وضع اشارة الحجز عليها لدى الدوائر المختصة.\nج-لغايات هذه المادة يتم بقرار من المجلس القضائي تكليف احدى هيئات محكمة استئناف قضايا ضريبة الدخل واحدى هيئات محكمة الجمارك البدائية واحدى هيئات محكمة الجمارك الاستئنافية، حسب مقتضى الحال، بعقد جلساتها في مدينة العقبة بمواعيد دورية.","title":"الاختصاص القضائي في القضايا الضريبية والجمركية","memo":"⭐ محكمة استئناف قضايا ضريبة الدخل: الطعن في قرارات تقدير ضريبة الدخل والغرامات والمبالغ الإضافية\n⭐ محكمة الجمارك البدائية (واستئنافها لدى محكمة الجمارك الاستئنافية): المخالفات الجمركية والطعن في تحديد المبالغ الخاضعة لضريبة المبيعات\n⭐ الإفراج عن البضائع المحجوزة لقاء كفالة مصرفية أو نقدية تعادل قيمتها\n⭐ المجلس القضائي يكلف هيئات المحاكم بعقد جلسات دورية في مدينة العقبة","qs":[{"q":"تختص بالنظر في الاستئنافات المقدمة للطعن في قرارات تقدير ضريبة الدخل في المنطقة:","o":["محكمة استئناف قضايا ضريبة الدخل","محكمة الجمارك البدائية","محكمة بداية العقبة","محكمة العدل العليا"],"a":0},{"q":"الطعن في القرارات المتعلقة بتحديد المبالغ الخاضعة لضريبة المبيعات وفق قانون المنطقة يكون أمام:","o":["محكمة الجمارك البدائية","محكمة استئناف قضايا ضريبة الدخل","محكمة بداية العقبة","محكمة صلح العقبة"],"a":0},{"q":"الجهة التي تكلف إحدى هيئات المحاكم المختصة بعقد جلساتها في مدينة العقبة بمواعيد دورية:","o":["المجلس القضائي","مجلس الوزراء","وزير العدل","رئيس السلطة"],"a":0},{"q":"يتم الإفراج عن البضائع المحجوزة في القضايا المنظورة لدى محكمة الجمارك لقاء:","o":["كفالة مصرفية أو نقدية تعادل قيمة هذه البضائع","كفالة عدلية بنصف قيمة البضائع","دفع غرامة تعادل مثلي القيمة","قرار من رئيس السلطة"],"a":0}]},{"n":"39","chapter":"","notes":[],"source":"تطبق العقوبات المنصوص عليها في قانون ضريبة الدخل النافذ المفعول على أي جرم يرتكب خلافا لأحكام هذا القانون والانظمة الصادرة بمقتضاه والمتعلقة بضريبة الدخل في المنطقة.","title":"عقوبات جرائم ضريبة الدخل في المنطقة","memo":"⭐ تطبق العقوبات المنصوص عليها في قانون ضريبة الدخل النافذ على أي جرم يتعلق بضريبة الدخل في المنطقة","qs":[{"q":"العقوبات المطبقة على الجرائم المتعلقة بضريبة الدخل في المنطقة هي العقوبات المنصوص عليها في:","o":["قانون ضريبة الدخل النافذ المفعول","قانون الجمارك","قانون العقوبات فقط","الأنظمة الصادرة عن مجلس المفوضين"],"a":0},{"q":"تسري عقوبات قانون ضريبة الدخل النافذ على الجرائم المرتكبة في المنطقة خلافاً لقانون المنطقة والأنظمة الصادرة بمقتضاه متى كانت متعلقة بـ:","o":["ضريبة الدخل في المنطقة","ضريبة المبيعات في المنطقة","المخالفات الجمركية","الجرائم البيئية"],"a":0}]},{"n":"39 مكرر أولاً","chapter":"","notes":[],"source":"أ-يعد تهربا من الضريبة المنصوص عليها في البند (1) من الفقرة (أ) من المادة (37) من هذا القانون والفقرة (ج) منها كل من ارتكب ايا من الافعال التالية:\n1-التخلف عن تقديم طلب التسجيل لدى السلطة مدة تزيد على شهر من تاريخ انقضاء المدة المحددة للتسجيل.\n2-التخلف عن تقديم الاقرار الضريبي مدة تزيد على شهر واحد من تاريخ انتهاء المدة المحددة لتقديم الاقرار الضريبي.\n3-تقديم اقرار بالمبيعات من السلع او الخدمات الخاضعة للضريبة إذا ظهر نقص في قيمة المبيعات الحقيقية الخاضعة للضريبة تتجاوز نسبته (%10) او ثلاثة الاف دينار ايهما اقل.\n4-عدم مسك سجلات محاسبية او بدائلها من الوسائل الفنية وترتب على ذلك نقص في مقدار الضريبة المصرح عنها او المستحقة تتجاوز مائتي دينار.\n5-الغاء تسجيل المكلف بناء على طلبه إذا ثبت للسلطة انه ما زال ملزما بالتسجيل وفق أحكام هذا القانون.\n6-استيفاء أي شخص ضريبة غير مستحقة الا إذا تم توريدها للسلطة خلال المدة التي يحددها القانون لتوريد الضريبة او تم توريدها قبل اكتشافها.\n7-التصرف في أي من السلع التي تم اعفاؤها من الضريبة او استعمالها في غير الغرض الذي اعفيت من اجله وادى ذلك إلى نقص يتجاوز مائتي دينار في مقدار الضريبة المستحقة.\n8-عدم تمكين موظفي السلطة من القيام بواجباتهم او ممارسة صلاحياتهم في الرقابة والتفتيش وفق أحكام هذا القانون.\n9-استيفاء المكلف لنسب او فئات ضريبية على السلع او الخدمات الخاضع للضريبة بصورة مخالفة لأحكام هذا القانون وادى ذلك إلى نقص في مقدار الضريبة المستحقة تجاوز مائتي دينار.\n10-تقديم مستندات او وثائق او بيانات غير صحيحة او اصدار أي منها وادى ذلك إلى نقص في مقدار الضريبة المصرح عنها او المستحقة تجاوز مائتي دينار.\n11-حيازة السلع الخاضعة للضريبة بقصد الاتجار بها وهو يعلم بانها مهربة من الضريبة.\nب-يعاقب كل من ارتكب ايا من الافعال المنصوص عليها في الفقرة (أ) من هذه المادة بدفع تعويض مدني للسلطة لا يقل عن مثلي الضريبة ولا يزيد على ثلاثة امثالها وبغرامة لا تقل عن مائتي دينار ولا تزيد على الف دينار وتضاعف الغرامة في حالة التكرار وإذا تكرر ارتكاب الفعل خلال مدة لا تزيد على سنة واحدة فللمحكمة ان تحكم بالحد الاعلى للغرامة او بالحبس مدة لا تقل عن ثلاثة اشهر ولا تزيد على ستة اشهر او بكلتا هاتين العقوبتين.\nج-للرئيس او من يفوضه عقد مصالحة في جرائم التهرب من الضريبة المنصوص عليها في الفقرة (أ) من هذه المادة وذلك قبل صدور حكم قطعي في الدعوى مقابل دفع الضريبة موضوع القضية وغرامة كتعويض مدني للسلطة تعادل مقدار الضريبة ، ويترتب على هذه المصالحة سقوط الدعوى الجزائية ووقف السير في اجراءاتها والغاء ما يترتب عليها من اثار.","title":"التهرب من ضريبة المبيعات وعقوبته","memo":"⭐ من صور التهرب: التخلف عن التسجيل أو تقديم الإقرار مدة تزيد على شهر؛ نقص في المبيعات يتجاوز (10%) أو (3000) دينار أيهما أقل؛ نقص في الضريبة يتجاوز (200) دينار\n⭐ العقوبة: تعويض مدني لا يقل عن مثلي الضريبة ولا يزيد على ثلاثة أمثالها + غرامة (200–1000) دينار تضاعف عند التكرار\n⭐ التكرار خلال سنة: الحد الأعلى للغرامة أو الحبس (3–6) أشهر أو كلتاهما\n⭐ المصالحة للرئيس أو من يفوضه قبل الحكم القطعي مقابل الضريبة وغرامة تعادلها، وتسقط الدعوى الجزائية","qs":[{"q":"يعد تهرباً من الضريبة التخلف عن تقديم الإقرار الضريبي مدة تزيد على:","o":["شهر واحد من تاريخ انتهاء المدة المحددة","ثلاثين يوماً من تاريخ التسجيل","ثلاثة أشهر من انتهاء السنة","ستة أشهر من تاريخ الاستحقاق"],"a":0},{"q":"يعد تقديم إقرار بالمبيعات تهرباً إذا ظهر نقص في قيمة المبيعات الحقيقية تتجاوز نسبته:","o":["(10%) أو ثلاثة آلاف دينار أيهما أقل","(10%) أو ثلاثة آلاف دينار أيهما أكثر","(15%) أو خمسة آلاف دينار أيهما أقل","(5%) أو ألف دينار أيهما أقل"],"a":0},{"q":"التعويض المدني المفروض على مرتكب التهرب من الضريبة:","o":["لا يقل عن مثلي الضريبة ولا يزيد على ثلاثة أمثالها","لا يقل عن مثل الضريبة ولا يزيد على مثليها","لا يقل عن ثلاثة أمثال الضريبة ولا يزيد على ستة أمثالها","يعادل مقدار الضريبة فقط"],"a":0},{"q":"حالة عملية: تهرب مكلف من الضريبة ثم أراد المصالحة قبل صدور حكم قطعي، فإن المصالحة تتم مقابل:","o":["دفع الضريبة وغرامة كتعويض مدني تعادل مقدار الضريبة","دفع الضريبة فقط","دفع الضريبة وغرامة تعادل ثلاثة أمثالها","دفع نصف الحد الأعلى للغرامة"],"a":0}]},{"n":"39 مكرر ثانياً","chapter":"","notes":[],"source":"أ-باستثناء الحالات المنصوص عليها في الفقرة (أ) من المادة (39) مكرر (اولا ) من هذا القانون للرئيس فرض غرامة لا تقل عن مائة دينار ولا تزيد على خمسمائة دينار على كل من ارتكب ايا من المخالفات التالية:\n1-التخلف عن تقديم طلب التسجيل لدى السلطة خلال مدة لا تزيد على شهر من تاريخ انتهاء المدة المحددة للتسجيل.\n2-التخلف عن تقديم الاقرار الضريبي خلال مدة لا تزيد على شهر من تاريخ انتهاء المواعيد المحددة لتقديم الاقرار.\n3-تقديم اقرار بالمبيعات من السلع او الخدمات الخاضعة للضريبة إذا ظهر نقص في قيمة المبيعات الحقيقية الخاضعة للضريبة لا تتجاوز (%10) او ثلاثة الاف دينار ايهما اقل.\n4-عدم مسك سجلات محاسبية او بدائلها من الوسائل الفنية.\n5-التخلف عن اعلام السلطة بالتغييرات التي طرأت على البيانات الواردة في طلب التسجيل خلال ثلاثين يوما من تاريخ التغيير.\n6-عدم الاستجابة دون عذر مبرر لأي من مذكرات الحضور او الاشعارات او الطلبات الصادرة خطيا عن موظفي السلطة اثناء قيامهم بواجباتهم او مسؤولياتهم وفق أحكام هذا القانون.\n7-التصرف في أي من السلع التي تم اعفاؤها من الضريبة او استعمالها في غير الغرض الذي اعفيت من اجله وادى ذلك إلى نقص لا يتجاوز مائتي دينار في مقدار الضريبة المستحقة.\n8-استيفاء المكلف لنسب او فئات ضريبية على السلع او الخدمات الخاضعة للضريبة بصورة مخالفة لأحكام هذا القانون وادى ذلك إلى نقص في مقدار الضريبة المستحقة لا يتجاوز مائتي دينار.\n9-تقديم مستندات او وثائق او بيانات غير صحيحة او اصدار أي منها وادى ذلك إلى نقص في مقدار الضريبة المصرح عنها او المستحقة لا يتجاوز مائتي دينار.\nب-يبلغ المخالف وفق الاصول المتبعة بالغرامة المفروضة عليه ، وعليه دفعها خلال ثلاثين يوما من تاريخ تبليغه.\nج-يجوز الاعتراض لدى الرئيس على قرارات التغريم الصادرة بمقتضى أحكام الفقرة (أ) من هذه المادة خلال المدة المحددة في الفقرة (ب) منها وللرئيس الغاء او تخفيض او تثبيت الغرامة إذا تبين ما يبرر ذلك . ويكون قرار الرئيس قابلا للطعن لدى المحكمة المختصة خلال ثلاثين يوما من تاريخ تبليغه ، وللمحكمة ان تؤيد الغرامة او تعدلها او تلغيها.\nد-للرئيس او من يفوضه اجراء المصالحة على المخالفات المنصوص عليها في الفقرة (أ) من هذه المادة مقابل دفع الضريبة في حال استحقاقها وغرامة لا تقل عن نصف الحد الادنى ولا تزيد على نصف الحد الاعلى من الغرامات المنصوص عليها في الفقرة (أ) منها وذلك قبل صدور حكم قطعي من المحكمة ، ويترتب على المصالحة وقف السير باجراءات الدعوى واسقاطها نهائيا والغاء ما يترتب عليها من اثار.","title":"مخالفات ضريبة المبيعات وغراماتها","memo":"⭐ للرئيس فرض غرامة (100–500) دينار على المخالفات التي لا تصل حد التهرب\n⭐ منها: التأخر في التسجيل أو الإقرار مدة لا تزيد على شهر، وعدم إعلام السلطة بتغيير البيانات خلال (30) يوماً\n⭐ تدفع الغرامة خلال (30) يوماً من التبليغ، ويُعترض لدى الرئيس، ثم يُطعن بقراره لدى المحكمة خلال (30) يوماً\n⭐ المصالحة بغرامة بين نصف الحد الأدنى ونصف الحد الأعلى قبل الحكم القطعي","qs":[{"q":"الغرامة التي يفرضها الرئيس على مخالفات ضريبة المبيعات المنصوص عليها في المادة (39 مكرر ثانياً):","o":["لا تقل عن (100) دينار ولا تزيد على (500) دينار","لا تقل عن (200) دينار ولا تزيد على (1000) دينار","لا تقل عن (50) ديناراً ولا تزيد على (5000) دينار","لا تقل عن (10) دنانير ولا تزيد على (500) دينار"],"a":0},{"q":"يعد مخالفة التخلف عن إعلام السلطة بالتغييرات التي طرأت على بيانات طلب التسجيل خلال:","o":["ثلاثين يوماً من تاريخ التغيير","شهرين من تاريخ التغيير","خمسة عشر يوماً من تاريخ التغيير","سنة من تاريخ التغيير"],"a":0},{"q":"يكون قرار الرئيس في الاعتراض على الغرامة قابلاً للطعن لدى المحكمة المختصة خلال:","o":["ثلاثين يوماً من تاريخ تبليغه","خمسة عشر يوماً من تاريخ تبليغه","ستين يوماً من تاريخ صدوره","عشرة أيام من تاريخ تبليغه"],"a":0},{"q":"حالة عملية: أرادت مؤسسة المصالحة على مخالفة عقوبتها غرامة (100–500) دينار، فإن غرامة المصالحة تكون:","o":["بين (50) و(250) ديناراً","بين (100) و(500) دينار","بين (200) و(1000) دينار","بين (25) و(125) ديناراً"],"a":0}]},{"n":"40","chapter":"","notes":[],"source":"أ-على كل مؤسسة مسجلة تنظيم حساباتها وبياناتها المالية وفقا لأحكام نظام خاص يصدر لهذه الغاية بما يتفق ومعايير المحاسبة الدولية.\nب-تلتزم المؤسسة المسجلة باظهار دخلها المتاتي من عملها داخل المملكة باستثناء المنطقة والنفقات المتعلقة به في بياناتها المالية بشكل منفصل عن دخلها المتحقق من نشاطها في المنطقة وخارج المملكة.\nج-تتولى السلطة تدقيق حسابات المؤسسة المسجلة وقيودها ودفاترها وسجلاتها وفق تعليمات يضعها المجلس لهذه الغاية.\nد-إذا لم تتقيد المؤسسة المسجلة بأحكام هذه المادة وبالتعليمات الصادرة عن المجلس يحق للرئيس الغاء تسجيلها وذلك دون اخلال بأي التزامات تترتب عليها وفقا للتشريعات السارية المفعول.","title":"حسابات المؤسسة المسجلة وتدقيقها","memo":"⭐ تنظم المؤسسة المسجلة حساباتها وفق نظام خاص بما يتفق ومعايير المحاسبة الدولية\n⭐ تُظهر دخلها المتأتي من عملها داخل المملكة (باستثناء المنطقة) بشكل منفصل عن دخلها في المنطقة وخارج المملكة\n⭐ تتولى السلطة تدقيق حساباتها وفق تعليمات يضعها المجلس\n⭐ عند عدم التقيد يحق للرئيس إلغاء تسجيلها","qs":[{"q":"تنظم المؤسسة المسجلة حساباتها وبياناتها المالية وفقاً لنظام خاص بما يتفق و:","o":["معايير المحاسبة الدولية","معايير المحاسبة الأمريكية","تعليمات البنك المركزي","تعليمات دائرة مراقبة الشركات"],"a":0},{"q":"الجهة التي تتولى تدقيق حسابات المؤسسة المسجلة وقيودها ودفاترها وفق تعليمات يضعها المجلس:","o":["السلطة","دائرة ضريبة الدخل","ديوان المحاسبة","مدقق حسابات تعينه وزارة الصناعة والتجارة"],"a":0},{"q":"إذا لم تتقيد المؤسسة المسجلة بأحكام تنظيم الحسابات والتعليمات الصادرة عن المجلس فإن للرئيس:","o":["إلغاء تسجيلها دون إخلال بالتزاماتها","فرض غرامة لا تقل عن مثلي الضريبة","إحالتها إلى محكمة بداية العقبة لتصفيتها","تعليق نشاطها مدة سنة"],"a":0}]},{"n":"41","chapter":"","notes":[],"source":"أ-على السلطة تزويد دائرة الضريبة العامة على المبيعات بالكشوفات والبيانات المتعلقة بمشتريات المؤسسات المسجلة من السلع والخدمات من المنطقة الجمركية ومبيعاتها إليها.\nب-لمدير عام دائرة الضريبة العامة على المبيعات او من يفوضه، إذا اقتضت المصلحة، الاطلاع على السجلات والوثائق المتعلقة بمبيعات ومشتريات المؤسسات المسجلة المتحققة في المنطقة الجمركية وفقا لأحكام هذا القانون.","title":"تبادل المعلومات مع دائرة الضريبة العامة على المبيعات","memo":"⭐ على السلطة تزويد دائرة الضريبة العامة على المبيعات بكشوف مشتريات المؤسسات المسجلة من المنطقة الجمركية ومبيعاتها إليها\n⭐ لمدير عام دائرة الضريبة العامة على المبيعات أو من يفوضه الاطلاع على السجلات إذا اقتضت المصلحة","qs":[{"q":"تلتزم السلطة بتزويد دائرة الضريبة العامة على المبيعات بالكشوفات المتعلقة بـ:","o":["مشتريات المؤسسات المسجلة من المنطقة الجمركية ومبيعاتها إليها","رواتب العاملين في المؤسسات المسجلة","مستوردات المؤسسات المسجلة من خارج المملكة فقط","أرباح المؤسسات المسجلة الموزعة"],"a":0},{"q":"يحق له الاطلاع على السجلات المتعلقة بمبيعات ومشتريات المؤسسات المسجلة المتحققة في المنطقة الجمركية إذا اقتضت المصلحة:","o":["مدير عام دائرة الضريبة العامة على المبيعات أو من يفوضه","وزير الصناعة والتجارة","رئيس مجلس المفوضين حصراً","مدير عام دائرة الجمارك"],"a":0}]},{"n":"42","chapter":"","notes":[],"source":"توزع الايرادات المتاتية وفقا لأحكام هذا القانون من ضريبتي الدخل والمبيعات على النحو التالي:\nأ-(%75) للخزينة ويتم تحويلها إلى وزارة المالية في نهاية كل شهر.\nب-(%25) للسلطة.","title":"توزيع إيرادات ضريبتي الدخل والمبيعات","memo":"⭐ (75%) للخزينة تُحوَّل إلى وزارة المالية في نهاية كل شهر\n⭐ (25%) للسلطة","qs":[{"q":"نسبة إيرادات ضريبتي الدخل والمبيعات المتأتية وفق قانون المنطقة التي تؤول إلى الخزينة:","o":["(75%)","(25%)","(50%)","(60%)"],"a":0},{"q":"تحول حصة الخزينة من إيرادات ضريبتي الدخل والمبيعات إلى وزارة المالية:","o":["في نهاية كل شهر","في نهاية كل سنة مالية","في نهاية كل ربع سنة","عند إقرار الحسابات الختامية"],"a":0}]},{"n":"43","chapter":"","notes":[],"source":"تنظيم الاراضي والابنية وادارة المناطق الساحلية:\nأ-تعتبر المنطقة والاقليم منطقة تنظيم اقليمي وفقا لأحكام قانون تنظيم المدن والقرى والابنية المعمول به والانظمة الصادرة بمقتضاه ويمارس المجلس لهذه الغاية صلاحيات مجلس التنظيم الاعلى ولجنتي التنظيم اللوائية والمحلية وله اناطة صلاحية هاتين اللجنتين بلجان خاصة يؤلفها لهذه الغاية كما ويمارس الرئيس ، حسب مقتضى الحال ، الصلاحيات المقررة للوزير في قانون تنظيم المدن والقرى والابنية المعمول به والانظمة الصادرة بمقتضاه ولمجلس الوزراء بناء على تنسيب المجلس ، وضع نظام خاص تحدد فيه اسس التنظيم والابنية في المنطقة وغيرها من الامور المتعلقة بها.\nب-يتولى المجلس ادارة المناطق السياحية ويتم تحديد اسس ادارة هذه المناطق على اليابسة وفي البحر وفقا لنظام يصدر لهذه الغاية.","title":"تنظيم الأراضي والأبنية وإدارة المناطق الساحلية","memo":"⭐ المنطقة والإقليم منطقة تنظيم إقليمي، ويمارس المجلس صلاحيات مجلس التنظيم الأعلى ولجنتي التنظيم اللوائية والمحلية\n⭐ يمارس الرئيس صلاحيات الوزير في قانون تنظيم المدن والقرى والأبنية\n⭐ لمجلس الوزراء بتنسيب المجلس وضع نظام خاص لأسس التنظيم والأبنية","qs":[{"q":"لغايات التنظيم في المنطقة يمارس المجلس صلاحيات:","o":["مجلس التنظيم الأعلى ولجنتي التنظيم اللوائية والمحلية","وزير الشؤون البلدية فقط","مجلس الوزراء","أمانة عمّان الكبرى"],"a":0},{"q":"يضع النظام الخاص الذي تحدد فيه أسس التنظيم والأبنية في المنطقة:","o":["مجلس الوزراء بناءً على تنسيب المجلس","المجلس بناءً على تنسيب الرئيس","رئيس السلطة منفرداً","وزير الشؤون البلدية"],"a":0},{"q":"يمارس الرئيس، حسب مقتضى الحال، الصلاحيات المقررة في قانون تنظيم المدن والقرى والأبنية لـ:","o":["الوزير","مجلس التنظيم الأعلى","اللجنة المحلية","المحافظ"],"a":0}]},{"n":"44","chapter":"","notes":[],"source":"أ-تنتقل إلى السلطة ملكية الاراضي المسجلة باسم الخزينة العامة التي تقع داخل حدود المنطقة وفقا لما يقرره مجلس الوزراء.\nب-لا يجوز للسلطة في أي حال بيع أي من الاراضي المشار إليها في الفقرة (أ) من هذه المادة الا وفق الاسس والشروط التي تحدد بمقتضى نظام خاص يصدر لهذه الغاية مع الاخذ بعين الاعتبار مبدأ المعاملة بالمثل.\nج-للسلطة حق التصرف في اراضي الدولة غير المسجلة باسم الخزينة بالتأجير او الاستثمار بمقتضى نظام يصدر لهذه الغاية.","title":"ملكية الأراضي في المنطقة والتصرف بها","memo":"⭐ تنتقل إلى السلطة ملكية أراضي الخزينة داخل المنطقة وفق ما يقرره مجلس الوزراء\n⭐ لا يجوز بيعها إلا وفق نظام خاص مع مراعاة مبدأ المعاملة بالمثل\n⭐ للسلطة التصرف في أراضي الدولة غير المسجلة باسم الخزينة بالتأجير أو الاستثمار بمقتضى نظام","qs":[{"q":"تنتقل إلى السلطة ملكية الأراضي المسجلة باسم الخزينة العامة داخل حدود المنطقة وفقاً لما يقرره:","o":["مجلس الوزراء","المجلس","وزير المالية","مدير عام دائرة الأراضي والمساحة"],"a":0},{"q":"بيع السلطة للأراضي التي انتقلت إليها ملكيتها من الخزينة:","o":["لا يجوز إلا وفق نظام خاص مع مراعاة مبدأ المعاملة بالمثل","جائز مطلقاً بقرار من الرئيس","محظور في جميع الأحوال","جائز لغير الأردنيين دون قيود"],"a":0},{"q":"تتصرف السلطة في أراضي الدولة غير المسجلة باسم الخزينة عن طريق:","o":["التأجير أو الاستثمار بمقتضى نظام","البيع المباشر","الهبة للمؤسسات المسجلة","الرهن لدى البنوك"],"a":0}]},{"n":"45","chapter":"","notes":[],"source":"على الرغم مما ورد في أي تشريع اخر، للسلطة ان تبرم عقود ايجار مع الغير لمدة لا تزيد على خمسين عاما، ويجوز لمجلس الوزراء بتنسيب من المجلس تمديد هذه المدة كما يراه مناسبا في حالات خاصة إذا كان الايجار متعلقا بنشاط استثماري في المنطقة.","title":"مدة عقود الإيجار","memo":"⭐ للسلطة إبرام عقود إيجار لمدة لا تزيد على (50) عاماً\n⭐ يجوز لمجلس الوزراء بتنسيب المجلس تمديدها في حالات خاصة إذا تعلق الإيجار بنشاط استثماري","qs":[{"q":"المدة القصوى لعقود الإيجار التي تبرمها السلطة مع الغير:","o":["خمسون عاماً","ثلاثون عاماً","تسعة وتسعون عاماً","خمسة وعشرون عاماً"],"a":0},{"q":"يجوز تمديد مدة عقد الإيجار الذي تبرمه السلطة في حالات خاصة إذا كان متعلقاً بنشاط استثماري بقرار من:","o":["مجلس الوزراء بتنسيب من المجلس","المجلس بتنسيب من الرئيس","الرئيس منفرداً","وزير المالية"],"a":0}]},{"n":"46","chapter":"","notes":[],"source":"على الرغم من أحكام أي تشريع اخر، يحق للمؤسسة المسجلة حيازة وتملك الاموال غير المنقولة الواقعة في المنطقة اللازمة لاعمالها والتصرف فيها وفقا للنظام الذي سيصدر بمقتضى المادة (44) من هذا القانون.","title":"تملك المؤسسة المسجلة للأموال غير المنقولة","memo":"⭐ يحق للمؤسسة المسجلة حيازة وتملك الأموال غير المنقولة في المنطقة اللازمة لأعمالها والتصرف فيها\n⭐ على الرغم من أي تشريع آخر، ووفق النظام الصادر بمقتضى المادة (44)","qs":[{"q":"يحق للمؤسسة المسجلة حيازة وتملك الأموال غير المنقولة الواقعة في المنطقة بشرط أن تكون:","o":["لازمة لأعمالها ووفقاً للنظام الصادر بمقتضى المادة (44)","مملوكة سابقاً لأردنيين","بموافقة مجلس الوزراء في كل حالة","لا تزيد مساحتها على دونم واحد"],"a":0},{"q":"يثبت حق المؤسسة المسجلة في تملك الأموال غير المنقولة في المنطقة والتصرف فيها:","o":["على الرغم من أحكام أي تشريع آخر","مع مراعاة قانون تملك غير الأردنيين للأموال غير المنقولة","بشرط الحصول على موافقة وزير الداخلية","في حدود الإيجار لمدة خمسين عاماً فقط"],"a":0}]},{"n":"47","chapter":"","notes":[],"source":"يقتصر تطبيق القوانين المتعلقة بحق الشفعة والاولوية على المناطق السكنية في المنطقة.","title":"حق الشفعة والأولوية","memo":"⭐ يقتصر تطبيق قوانين الشفعة والأولوية على المناطق السكنية في المنطقة","qs":[{"q":"يقتصر تطبيق القوانين المتعلقة بحق الشفعة والأولوية في المنطقة على:","o":["المناطق السكنية","المناطق الصناعية","المناطق السياحية","جميع أراضي المنطقة"],"a":0}]},{"n":"48","chapter":"","notes":[],"source":"يصدر مجلس الوزراء بناء على تنسيب المجلس انظمة خاصة تحدد بموجبها اسس وشروط واجراءات الدخول لغير الاردنيين إلى المنطقة والاقامة فيها وبخاصة ما يتعلق منها بما يلي:\nأ-تاشيرة دخول غير الاردنيين إلى المنطقة بما في ذلك تاشيرة الدخول المؤقتة التي تمنح من مراكز العبور مباشرة.\nب-اذن الاقامة في المنطقة.\nت- اسس استقدام العمالة الوافدة واستخدامها في المنطقة وتصاريح العمل لغير الاردنيين ونسبتهم إلى مجموع العاملين في المؤسسات المسجلة.\nث- الرسوم التي تستوفيها السلطة مقابل اصدار تاشيرة الدخول واذن الاقامة وتصريح العمل وفقا لهذه الانظمة.","title":"دخول غير الأردنيين وإقامتهم وعملهم","memo":"⭐ يصدر مجلس الوزراء بتنسيب المجلس أنظمة تحدد أسس دخول غير الأردنيين وإقامتهم\n⭐ تشمل: تأشيرة الدخول (ومنها المؤقتة من مراكز العبور)، إذن الإقامة، استقدام العمالة الوافدة ونسبتها، والرسوم التي تستوفيها السلطة","qs":[{"q":"الجهة التي تصدر الأنظمة الخاصة بأسس دخول غير الأردنيين إلى المنطقة والإقامة فيها:","o":["مجلس الوزراء بناءً على تنسيب المجلس","وزير الداخلية","المجلس بتنسيب من الرئيس","مدير الأمن العام"],"a":0},{"q":"أي مما يلي لا يُعد من الأمور التي تنظمها الأنظمة الصادرة بموجب المادة الخاصة بدخول غير الأردنيين؟","o":["منح الجنسية الأردنية","تأشيرة الدخول المؤقتة من مراكز العبور","نسبة العمالة الوافدة إلى مجموع العاملين في المؤسسات المسجلة","الرسوم مقابل إصدار إذن الإقامة وتصريح العمل"],"a":0},{"q":"الرسوم مقابل إصدار تأشيرة الدخول وإذن الإقامة وتصريح العمل في المنطقة تستوفيها:","o":["السلطة","وزارة الداخلية","وزارة العمل","دائرة الجمارك"],"a":0}]},{"n":"49","chapter":"","notes":[],"source":"أ-يجوز لأي مؤسسة مسجلة او مستثمر في المنطقة او أي شخص استعمال العملة الاردنية او الاجنبية في أي صفقة تجارية او لأي غرض شخصي بما في ذلك فتح حسابات بنكية بأي عملة وكذلك شراء العملات الاجنبية وبيعها.\nب-يسمح للمؤسسات المسجلة في المنطقة بادخال العملات الاجنبية او تحويلها من المنطقة دون قيود.","title":"حرية التعامل بالعملات","memo":"⭐ يجوز استعمال العملة الأردنية أو الأجنبية في أي صفقة أو غرض شخصي، وفتح حسابات بأي عملة وشراء وبيع العملات\n⭐ يسمح للمؤسسات المسجلة بإدخال العملات الأجنبية أو تحويلها من المنطقة دون قيود","qs":[{"q":"وفق قانون المنطقة، يجوز استعمال العملة الأجنبية في الصفقات التجارية في المنطقة لـ:","o":["أي مؤسسة مسجلة أو مستثمر أو أي شخص","المؤسسات المسجلة فقط","البنوك المرخصة فقط","غير الأردنيين فقط"],"a":0},{"q":"إدخال المؤسسات المسجلة للعملات الأجنبية إلى المنطقة أو تحويلها منها:","o":["مسموح دون قيود","مسموح بموافقة البنك المركزي","مسموح في حدود سقف يحدده المجلس","غير مسموح إلا للبنوك"],"a":0}]},{"n":"50","chapter":"","notes":[],"source":"تسري أحكام قانون البنوك والبنك المركزي على أي بنك او شركة مالية تقوم بالاعمال المصرفية في المنطقة او تفتح فروعا فيها.","title":"البنوك والشركات المالية في المنطقة","memo":"⭐ تسري أحكام قانون البنوك والبنك المركزي على أي بنك أو شركة مالية تمارس الأعمال المصرفية في المنطقة أو تفتح فروعاً فيها","qs":[{"q":"البنك الذي يمارس الأعمال المصرفية في المنطقة يخضع لأحكام:","o":["قانون البنوك وقانون البنك المركزي","أنظمة خاصة يصدرها المجلس بدلاً من قانون البنوك","قانون الشركات فقط","تعليمات رئيس السلطة"],"a":0}]},{"n":"51","chapter":"","notes":[],"source":"يجوز لأي شركة تامين القيام باعمال التامين في المنطقة او فتح فرع فيها وفقا لأحكام قانون مراقبة اعمال التامين.","title":"شركات التأمين في المنطقة","memo":"⭐ يجوز لأي شركة تأمين ممارسة أعمال التأمين في المنطقة أو فتح فرع فيها وفق قانون مراقبة أعمال التأمين","qs":[{"q":"تمارس شركات التأمين أعمالها في المنطقة أو تفتح فروعاً فيها وفقاً لأحكام:","o":["قانون مراقبة أعمال التأمين","قانون البنوك","نظام يصدره المجلس","قانون الشركات فقط"],"a":0}]},{"n":"52","chapter":"","notes":[],"source":"تنفيذا لأحكام هذا القانون يتولى المجلس مسؤولية حماية البيئة في المنطقة والمحافظة عليها وضمان التنمية المستدامة وفق اسس ومعايير تحدد بمقتضى نظام على ان لا تقل عن المستوى المعتمد في المملكة، ولهذه الغاية تمارس السلطة صلاحيات المؤسسة العامة لحماية البيئة كما يمارس الرئيس، حسب مقتضى الحال، الصلاحيات المقررة للوزير والمدير العام المنصوص عليها في قانون حماية البيئة المعمول بها.","title":"حماية البيئة في المنطقة","memo":"⭐ يتولى المجلس مسؤولية حماية البيئة وضمان التنمية المستدامة وفق نظام لا تقل معاييره عن المستوى المعتمد في المملكة\n⭐ تمارس السلطة صلاحيات المؤسسة العامة لحماية البيئة، والرئيس صلاحيات الوزير والمدير العام في قانون حماية البيئة","qs":[{"q":"الجهة التي تتولى مسؤولية حماية البيئة في المنطقة والمحافظة عليها وضمان التنمية المستدامة:","o":["المجلس","وزارة البيئة","مجلس الوزراء","محكمة بداية العقبة"],"a":0},{"q":"يشترط في أسس ومعايير حماية البيئة في المنطقة التي تحدد بمقتضى نظام:","o":["ألا تقل عن المستوى المعتمد في المملكة","أن تطابق المعايير الأوروبية","ألا تزيد على المستوى المعتمد في المملكة","أن يقرها وزير البيئة"],"a":0},{"q":"لغايات حماية البيئة في المنطقة تمارس السلطة صلاحيات:","o":["المؤسسة العامة لحماية البيئة","وزارة المياه والري","سلطة المصادر الطبيعية","مجلس التنظيم الأعلى"],"a":0}]},{"n":"52 مكرر","chapter":"","notes":[],"source":"أ-تختص محكمة بداية العقبة بالاضافة إلى اختصاصاتها بموجب التشريعات الاخرى النافذة المفعول بالنظر فيما يلي:\n1-الجرائم البيئية التي ترتكب خلافا لأحكام هذا القانون والانظمة الصادرة بمقتضاه.\n2-فرض الغرامات والتعويضات والمبالغ المستحقة عند وقوع حوادث التلوث البيئي واستيفاؤها وفقا لأحكام هذا القانون والانظمة الصادرة بمقتضاه.\n3-توقيف الاشخاص المسند اليهم ارتكاب الجرائم المنصوص عليها في البند (1) من هذه الفقرة واخلاء سبيلهم وفق أحكام قانون اصول المحاكمات الجزائية المعمول به . وفي الحالات التي لم تكن القضية قد وردت إلى المحكمة بعد يجوز لرئيس المحكمة ان يطلب من الشخص الذي اسندت اليه التهمة ان يقدم كفالة نقدية او عدلية لضمان حضوره للمحكمة والا يقرر توقيفه لحين صدور حكم قطعي من المحكمة المختصة او تقديم تلك الكفالة.\n4-الافراج عن البضائع المحجوزة في القضايا المنظورة لديها لقاء كفالة نقدية او مصرفية تعادل قيمة هذه البضائع وكذلك الافراج عن وسائط النقل المحجوزة بعد اتخاذ الاجراءات المناسبة بشأنها.\nب-\n1-يجوز ان تنعقد المحكمة من تلقاء نفسها خارج اوقات الدوام الرسمي وفي أي مكان يراه رئيس المحكمة مناسبا.\n2-في الحالات الطارئة او إذا استدعت المصلحة العامة ذلك تنعقد المحكمة وبناء على طلب الرئيس على الوجه المنصوص عليه في البند (1) من هذه الفقرة للنظر في أي قضية تتعلق بالمخالفات البيئية التي يحيلها إليها الرئيس بصفة مستعجلة لا تحتمل التأخير.","title":"اختصاص محكمة بداية العقبة في القضايا البيئية","memo":"⭐ تختص محكمة بداية العقبة بالجرائم البيئية وغرامات وتعويضات التلوث البيئي وتوقيف المتهمين والإفراج عن البضائع لقاء كفالة نقدية أو مصرفية تعادل قيمتها\n⭐ يجوز أن تنعقد المحكمة خارج أوقات الدوام الرسمي وفي أي مكان يراه رئيسها مناسباً\n⭐ في الحالات الطارئة تنعقد بناءً على طلب الرئيس للنظر بصفة مستعجلة في المخالفات البيئية","qs":[{"q":"المحكمة المختصة بالنظر في الجرائم البيئية المرتكبة خلافاً لقانون المنطقة:","o":["محكمة بداية العقبة","محكمة الجمارك البدائية","محكمة استئناف قضايا ضريبة الدخل","محكمة صلح العقبة"],"a":0},{"q":"يجوز أن تنعقد محكمة بداية العقبة للنظر في القضايا البيئية:","o":["من تلقاء نفسها خارج أوقات الدوام الرسمي وفي أي مكان يراه رئيس المحكمة مناسباً","في مقر السلطة فقط","بقرار من وزير العدل","خلال أوقات الدوام الرسمي حصراً"],"a":0},{"q":"في الحالات الطارئة تنعقد المحكمة للنظر في المخالفات البيئية بصفة مستعجلة بناءً على طلب:","o":["الرئيس","وزير البيئة","النائب العام","المجلس القضائي"],"a":0}]},{"n":"53","chapter":"","notes":[],"source":"أ-لمقاصد تنفيذ هذا القانون ، يعتبر من رجال الضابطة العدلية الرئيس او أي من اعضاء المجلس او الموظف المفوض من أي منهم وفقا للصلاحيات المقررة له . وللموظف المفوض الحق في ضبط أي مخالفة لأحكام هذا القانون والانظمة الصادرة بمقتضاه والتفتيش داخل المنطقة عن البضائع المحظور دخولها إليها او انتاجها او تخزينها فيها ويجوز له لهذه الغاية دخول أي مكان وتدقيق المستندات وتفتيش الاشخاص والبضائع والسفن والتحفظ على أي منها ويشمل هذا الحق اتخاذ الاجراءات الخاصة بحماية البيئة.\nب-\n1-على الرغم مما ورد في هذا القانون وفي أي تشريع اخر ، يكون للرئيس واعضاء المجلس لموظفي السلطة الحق في ضبط أي مخالفات ترتكب في الاقليم خلافا لأحكام هذا القانون والانظمة الصادرة بمقتضاه او أي تشريع اخر ساري المفعول ، واحالة المخالفات إلى المحكمة المختصة وفقا لأحكام هذا القانون والتشريعات ذات العلاقة.\n2-يستثنى من أحكام البند (1) من هذه الفقرة ما يلي:\n1-مخالفات التعدي على الاثار والمواقع الاثرية في الاقليم اذ يتوجب ضبط هذه المخالفات واتخاذ الاجراءات اللازمة بحق مرتكبيها وفقا لقانون الاثار المعمول بها.\n2-المخالفات الجمركية المنصوص عليها في قانون الجمارك المعمول به.","title":"الضابطة العدلية في المنطقة والإقليم","memo":"⭐ يعد من الضابطة العدلية: الرئيس وأعضاء المجلس والموظف المفوض\n⭐ للموظف المفوض ضبط المخالفات والتفتيش ودخول أي مكان وتفتيش الأشخاص والبضائع والسفن\n⭐ يستثنى من صلاحية الضبط في الإقليم: مخالفات التعدي على الآثار (وفق قانون الآثار)، والمخالفات الجمركية في قانون الجمارك","qs":[{"q":"لمقاصد تنفيذ قانون المنطقة يعتبر من رجال الضابطة العدلية:","o":["الرئيس وأعضاء المجلس والموظف المفوض من أي منهم","رئيس الوزراء والوزراء","قضاة محكمة بداية العقبة","موظفو دائرة ضريبة الدخل فقط"],"a":0},{"q":"أي مما يلي يستثنى من صلاحية الرئيس وأعضاء المجلس وموظفي السلطة في ضبط المخالفات المرتكبة في الإقليم؟","o":["مخالفات التعدي على الآثار والمواقع الأثرية","مخالفات الأنظمة الصادرة بمقتضى قانون المنطقة","مخالفات حماية البيئة","مخالفات تنظيم الأبنية"],"a":0},{"q":"يحق للموظف المفوض لغايات ضبط المخالفات والتفتيش في المنطقة:","o":["دخول أي مكان وتدقيق المستندات وتفتيش الأشخاص والبضائع والسفن","إصدار أحكام بالحبس","فرض غرامات تزيد على عشرة آلاف دينار","مصادرة البضائع نهائياً دون حكم"],"a":0}]},{"n":"54","chapter":"","notes":[],"source":"أ-يعاقب بالحبس مدة لا تقل عن شهر ولا تزيد على سنة او بغرامة لا تقل عن (100) دينار ولا تزيد على (5000) دينار او بكلتا هاتين العقوبتين كل من قام في المنطقة بما يلي:\n1-الاخلال بأي من أحكام وشروط الترانزيت او التصنيع الداخلي او الادخال المؤقت او الكفالات والتعهدات التي تطلبها السلطة على أي بضائع او اعادة التصدير القانونية او الواردة في الانظمة الصادرة بموجب هذا القانون.\n2-قطع الرصاص الجمركي او نزع الاختام او الازرار الجمركية عن البضائع المرسلة بالنقل بالعبور او المعدة للاخراج او اعادة التصدير.\n3-عدم احتفاظ الناقل والمؤسسة بالقيود والسجلات الملزمة بها بموجب أحكام هذا القانون والانظمة الصادرة بمقتضاه.\n4-عدم تقيد المخلصين الجمركيين بالانظمة التي تحدد واجباتهم.\n5-مخالفة أي شخص أحكام النظام المشار اليه في الفقرة (ب) من المادة (29) من هذا القانون او عدم تقيده بأي التزام مفروض بموجبه.\nب-يعاقب بالحبس مدة لا تقل عن ثلاثة اشهر ولا تزيد على سنتين او بغرامة لا تقل عن (300) دينار ولا تزيد على (10000) دينار او بكلتا هاتين العقوبتين كل من قام في المنطقة بما يلي:\n1-تفريغ البضائع على أي وسيلة نقل او حملها بصورة مغايرة للقانون والانظمة الصادرة بمقتضاه ، او رسو السفن او هبوط الطائرات او وقوف وسائط النقل الاخرى في غير الاماكن المحددة لها من السلطة او في الحالات الطارئة دون اعلام اقرب مركز جمركي بذلك ، او مغادرة السفن والطائرات او وسائط النقل الاخرى للمرفأ او للحرم الجمركي دون ترخيص من السلطة.\n2-نقل او حيازة البضائع بصورة مخالفة لأحكام القانون والانظمة الصادرة بمقتضاه.\n3-ادخال او اخراج او حيازة او نقل أي بضائع محظورة او ممنوع استيرادها او المقيدة دون تقديم اثباتات تؤيد بصورة نظامية او عدم اعادة استيراد البضائع الممنوع تصديرها والمصدرة مؤقتا لأي غاية كانت.\n4-اعاقة أي من موظفي السلطة من القيام بواجباته وفق أحكام القانون والانظمة الصادرة بمقتضاه ومن ممارسة حقهم في التفتيش والتدقيق والمعاينة وعدم الامتثال إلى طلبهم بالوقوف.\n5-تغيير ممر العبور المحدد من قبل السلطة او عدم اتباع الطرق او الاجراءات المحددة في ادخال البضائع إلى المنطقة واخراجها منها.\n6-التصرف في البضائع المدخلة إلى المنطقة تحت وضع الادخال المؤقت او وفق وضع العبور وذلك خلافا لأحكام هذا القانون والنظام الصادر بمقتضى أحكام هذا القانون والمتعلق بالجمارك او استخدامها في غير الاماكن المخصصة لها او لغير غايات استيرادها او في غير الغايات المخصصة لها او نقل المسافرين او البضائع داخل المنطقة بالسيارات المقبولة في وضع معلق للرسم بصورة مخالفة لأحكام القوانين والانظمة.\n7-تقديم تصريح او بيان او وثائق كاذبة او مزورة او وضع علامات كاذبة بقصد استيراد او تصدير بضائع محظورة او ممنوعة او مقيدة او خلافا لأحكام هذا القانون والنظام الصادر بمقتضى أحكام هذا القانون والمتعلق بالجمارك.\n8-اكتشاف بضائع غير مصرح عنها موضوعة في مخابئ بقصد اخفائها او في فجوات او فراغات غير مخصصة لاحتواء مثل هذه البضائع او تجاوز المراكز الجمركية بالبضائع دون التصريح عنها.\n9-عدم وجود بيان حمولة اصولي او ما يقوم مقامه او وجود بيان حمولة مغاير لحقيقة الحمولة او عدم التصريح عند الادخال او الاخراج عن البضائع الواردة او الصادرة دون بيان حمولة ويدخل في ذلك ما يصحبه المسافرون.\n10-تفريغ البضائع او تحميلها دون اذن مسبق من السلطة او تفريغها او تحميلها من غير المواقع المحددة لذلك من قبل السلطة او في مواقع غير مراكز الدخول والخروج المحددة من دائرة الجمارك.\n11-الزيادة او النقص او التبديل في عدد الطرود او في محتوياتها والمكتشفة بعد مغادرة البضاعة مركز الادخال او النقص او الزيادة غير المبررة عما ادرج في بيان الحمولة او ما يقوم مقامه ، وسواء في عدد الطرود او في محتوياتها او في كميات البضائع المنفرطة.\nج-بالاضافة إلى ما ورد في الفقرتين (أ) و (ب) من هذه المادة ، تستوفى الغرامات التالية في الحالات المبينة ادناه:\n1-من ثلاثة امثال القيمة إلى ستة امثال القيمة إذا كانت البضائع موضوع المخالفة من البضائع المحظورة او الممنوعة مع مصادرة البضائع المخالفة.\n2-من مثلي القيمة إلى ثلاثة امثال القيمة إذا كانت البضائع موضوع المخالفة من البضائع المقيدة.\n3-من مثل القيمة إلى مثلي القيمة إذا كانت البضائع موضوع المخالفة من غير البضائع المحظورة او الممنوعة او المقيدة.","title":"العقوبات الجمركية في المنطقة","memo":"⭐ الفقرة (أ): حبس من شهر إلى سنة أو غرامة (100–5000) دينار أو كلتاهما، مثل قطع الرصاص الجمركي وعدم احتفاظ الناقل بالقيود\n⭐ الفقرة (ب): حبس من (3) أشهر إلى سنتين أو غرامة (300–10000) دينار أو كلتاهما، مثل البضائع في مخابئ والوثائق المزورة\n⭐ غرامات إضافية: المحظورة (3–6) أمثال القيمة مع المصادرة، المقيدة (2–3) أمثال، غيرها (1–2) مثل","qs":[{"q":"عقوبة قطع الرصاص الجمركي أو نزع الأختام عن البضائع المرسلة بالعبور في المنطقة:","o":["الحبس من شهر إلى سنة أو غرامة من (100) إلى (5000) دينار أو كلتاهما","الحبس من ثلاثة أشهر إلى سنتين أو غرامة من (300) إلى (10000) دينار أو كلتاهما","الحبس من أسبوع إلى سنة أو غرامة من (10) إلى (5000) دينار","غرامة من (100) إلى (500) دينار فقط"],"a":0},{"q":"حالة عملية: اكتُشفت بضائع غير مصرح عنها في مخابئ بقصد إخفائها، فإن العقوبة هي:","o":["الحبس من ثلاثة أشهر إلى سنتين أو غرامة من (300) إلى (10000) دينار أو كلتاهما","الحبس من شهر إلى سنة أو غرامة من (100) إلى (5000) دينار أو كلتاهما","الحبس من سنة إلى ثلاث سنوات","غرامة لا تتجاوز ألف دينار يفرضها المفوض المختص"],"a":0},{"q":"الغرامة الإضافية إذا كانت البضائع موضوع المخالفة من البضائع المحظورة أو الممنوعة:","o":["من ثلاثة أمثال القيمة إلى ستة أمثالها مع المصادرة","من مثلي القيمة إلى ثلاثة أمثالها","من مثل القيمة إلى مثليها","من نصف القيمة إلى مثلها"],"a":0},{"q":"الغرامة الإضافية إذا كانت البضائع موضوع المخالفة من البضائع المقيدة:","o":["من مثلي القيمة إلى ثلاثة أمثال القيمة","من ثلاثة أمثال القيمة إلى ستة أمثالها","من مثل القيمة إلى مثليها","ستة أمثال القيمة"],"a":0}]},{"n":"54 مكرر أولاً","chapter":"","notes":[],"source":"مع مراعاة أحكام المادتين (54) و (54 مكرر ( ثانيا )) من هذا القانون ودون الاخلال بأي عقوبة اشد ينص عليها أي تشريع اخر ، يعاقب كل من يخالف أحكام هذا القانون والانظمة الصادرة بمقتضاه او أي تشريع اخر ساري المفعول في المنطقة بالحبس مدة لا تقل عن اسبوع ولا تزيد على سنة او بغرامة لا تقل عن عشرة دنانير ولا تزيد على خمسة الاف دينار او بكلتا هاتين العقوبتين ، مع الزام المخالف بالتعويض وازالة الضرر الناشئ عن المخالفة.","title":"العقوبة العامة لمخالفة القانون","memo":"⭐ العقوبة العامة: حبس من أسبوع إلى سنة أو غرامة (10–5000) دينار أو كلتاهما\n⭐ مع إلزام المخالف بالتعويض وإزالة الضرر، ودون الإخلال بأي عقوبة أشد","qs":[{"q":"العقوبة العامة لمن يخالف أحكام قانون المنطقة والأنظمة الصادرة بمقتضاه (مع مراعاة المادتين 54 و54 مكرر ثانياً):","o":["الحبس من أسبوع إلى سنة أو غرامة من عشرة دنانير إلى خمسة آلاف دينار أو كلتاهما","الحبس من شهر إلى سنة أو غرامة من مائة إلى خمسة آلاف دينار","الحبس من ثلاثة أشهر إلى سنتين أو غرامة من ثلاثمائة إلى عشرة آلاف دينار","غرامة من مائة إلى خمسمائة دينار فقط"],"a":0},{"q":"بالإضافة إلى العقوبة العامة الواردة في المادة (54 مكرر أولاً) يلزم المخالف بـ:","o":["التعويض وإزالة الضرر الناشئ عن المخالفة","دفع (15%) بدل نفقات إدارية","مغادرة المنطقة","إلغاء تسجيله حكماً"],"a":0}]},{"n":"54 مكرر ثانياً","chapter":"","notes":[],"source":"أ-دون الاخلال بأي عقوبة اشد ينص عليها أي تشريع اخر ، يعاقب بالعقوبات المبينة ادناه كل من يخالف أحكام هذا القانون والانظمة الصادرة بمقتضاه او أي تشريع اخر ساري المفعول في المنطقة والتي تتعلق بمياه البحر او البيئة مع الزام المخالف بالتعويض وازالة الضرر الناشئ عن المخالفة:\n1-بالحبس مدة لا تقل عن اسبوع ولا تزيد على ستة اشهر وبغرامة لا تقل عن خمسين دينارا ولا تزيد على عشرة الاف دينار كل من لوث مياه البحر او الحق ضررا بالبيئة بأي طريقة كانت وبأي مادة من غير المواد المشار إليها في البند (2) من هذه الفقرة ، او خالف ايا من الأحكام او الاجراءات او الشروط المنصوص عليها في الانظمة الصادرة بمقتضى هذا القانون المتعلقة بحماية البيئة.\n2-بالحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات وبغرامة لا تقل عن خمسين الف دينار ولا تزيد على عشرة ملايين دينار او بكلتا هاتين العقوبتين ، كل من لوث البحر بصورة جسيمة او الحق ضررا جسيما بالبيئة عن طريق طرح أي مواد فيها ذات اثار جسيمة على البيئة والتي يتعذر ازالتها ، او التي على الرغم من ازالتها تؤثر سلبا على السير الطبيعي للنظم البيئية ، او التي تعيق سلامة واستقرار هذه النظم واستخداماتها بأي شكل ، وتحدد هذه المواد وكمياتها واثارها بمقتضى نظام يصدر لهذه الغاية على ان يراعى فيه ما هو متبع دوليا بهذا الشأن\nب-يتوجب على من يرتكب ايا من المخالفات المشار إليها في الفقرة (أ) من هذه المادة ازالة اسبابها خلال المدة التي تحددها المحكمة وفي حال تخلفه عن القيام بذلك تتولى السلطة ازالتها على نفقته مضافا إليها (%15) من قيمتها وذلك بدل نفقات ادارية وتغريمه بمبلغ لا يقل عن مائة دينار ولا يزيد على خمسمائة دينار عن كل يوم يتخلف فيه عن ازالة اسباب المخالفة بعد المدة التي تحددها المحكمة لذلك ووضع مصدر المخالفة تحت الحجز لحين دفع جميع المبالغ المترتبة على المسؤول.","title":"عقوبات تلويث مياه البحر والبيئة","memo":"⭐ التلويث العادي: حبس أسبوع–6 أشهر وغرامة (50–10000) دينار\n⭐ التلويث الجسيم: حبس سنة–3 سنوات وغرامة (50,000) دينار–(10) ملايين دينار أو كلتاهما\n⭐ إن تخلف عن إزالة الأسباب: تزيلها السلطة على نفقته + (15%) نفقات إدارية + غرامة (100–500) دينار عن كل يوم تأخير، ووضع مصدر المخالفة تحت الحجز","qs":[{"q":"عقوبة من لوث البحر بصورة جسيمة أو ألحق ضرراً جسيماً بالبيئة بطرح مواد ذات آثار جسيمة:","o":["الحبس من سنة إلى ثلاث سنوات وغرامة من خمسين ألف دينار إلى عشرة ملايين دينار أو كلتاهما","الحبس من أسبوع إلى ستة أشهر وغرامة من خمسين ديناراً إلى عشرة آلاف دينار","الحبس من ثلاثة أشهر إلى سنتين وغرامة من (300) إلى (10000) دينار","الحبس من شهر إلى سنة وغرامة من (100) إلى (5000) دينار"],"a":0},{"q":"إذا تخلف المخالف عن إزالة أسباب المخالفة البيئية خلال المدة التي تحددها المحكمة، تتولى السلطة إزالتها على نفقته مضافاً إليها بدل نفقات إدارية نسبته:","o":["(15%)","(10%)","(25%)","(5%)"],"a":0},{"q":"الغرامة اليومية على المخالف عن كل يوم يتخلف فيه عن إزالة أسباب المخالفة البيئية بعد المدة المحددة:","o":["لا تقل عن (100) دينار ولا تزيد على (500) دينار","لا تقل عن (50) ديناراً ولا تزيد على (1000) دينار","لا تقل عن (10) دنانير ولا تزيد على (100) دينار","لا تقل عن (500) دينار ولا تزيد على (5000) دينار"],"a":0}]},{"n":"54 مكرر ثالثاً","chapter":"","notes":[],"source":"أ-تفرض بقرار من المفوض المختص او من يفوضه الغرامات التي لا يتجاوز مقدارها الف دينار.\nب-يبلغ المخالف او من يمثله بالغرامة المفروضة عليه بموجب اشعار خطي او بالبريد المسجل وعلى المخالف دفع الغرامات خلال ثلاثين يوما من تاريخ تبلغه او رفض التوقيع على اشعار التبليغ.","title":"فرض الغرامات وتبليغها","memo":"⭐ يفرض المفوض المختص أو من يفوضه الغرامات التي لا يتجاوز مقدارها (1000) دينار\n⭐ يبلَّغ المخالف بإشعار خطي أو بالبريد المسجل، ويدفع خلال (30) يوماً من التبلغ أو رفض التوقيع","qs":[{"q":"تفرض الغرامات التي لا يتجاوز مقدارها ألف دينار بقرار من:","o":["المفوض المختص أو من يفوضه","الرئيس حصراً","المحكمة المختصة","مجلس الوزراء"],"a":0},{"q":"يدفع المخالف الغرامة المفروضة عليه بموجب المادة (54 مكرر ثالثاً) خلال:","o":["ثلاثين يوماً من تاريخ تبلغه أو رفضه التوقيع على إشعار التبليغ","خمسة عشر يوماً من تاريخ صدور القرار","ستين يوماً من تاريخ التبليغ","سبعة أيام من تاريخ المخالفة"],"a":0}]},{"n":"54 مكرر رابعاً","chapter":"","notes":[],"source":"أ-يجوز الاعتراض لدى الرئيس على قرارات التغريم الصادرة بمقتضى المادة (54 مكرر ( ثالثا ) ) من هذا القانون خلال المدة المحددة فيها وللرئيس ولاسباب مبررة المصادقة على اقرار التغريم او تخفيضه او الغائه.\nب-يكون قرار الرئيس الذي يصدره بموجب الفقرة (أ) من هذه المادة قابلا للطعن لدى المحكمة المختصة وفقا لأحكام هذا القانون خلال ثلاثين يوما من تاريخ تبليغه إذا تجاوزت الغرامة الف دينار.","title":"الاعتراض على قرارات التغريم والطعن فيها","memo":"⭐ يجوز الاعتراض لدى الرئيس على قرارات التغريم، وله لأسباب مبررة المصادقة أو التخفيض أو الإلغاء\n⭐ قرار الرئيس قابل للطعن لدى المحكمة المختصة خلال (30) يوماً من تبليغه إذا تجاوزت الغرامة (1000) دينار","qs":[{"q":"يقدم الاعتراض على قرارات التغريم الصادرة عن المفوض المختص إلى:","o":["الرئيس","المجلس","محكمة بداية العقبة مباشرة","وزير المالية"],"a":0},{"q":"يكون قرار الرئيس في الاعتراض على التغريم قابلاً للطعن لدى المحكمة المختصة خلال ثلاثين يوماً من تبليغه إذا:","o":["تجاوزت الغرامة ألف دينار","تجاوزت الغرامة خمسمائة دينار","كانت المخالفة بيئية فقط","وافق الرئيس على الطعن"],"a":0}]},{"n":"54 مكرر خامساً","chapter":"","notes":[],"source":"أ-للرئيس او للمفوض المختص ، ولاسباب مبررة ، عقد تسوية صلحية في القضايا الجمركية التي ينص عليها النظام الصادر بمقتضى المادة (29) من هذا القانون سواء قبل اقامة الدعوى او خلال النظر فيها وقبل صدور الحكم البدائي وتتم التسوية مع الجهة المخالفة وفقا لأحكام وشروط عقد المصالحة على ان يبين فيه جميع مبالغ التعويضات والنفقات التي يتحملها المخالف ولا يجوز ان تتم التسوية باقل من نصف الحد الادنى المنصوص عليه في هذا القانون\nب-يصدر الرئيس او من يفوضه دليلا بالتسويات الصلحية المشار إليها في الفقرة (أ) من هذه المادة ويتم نشره في الجريدة الرسمية\nج-تسقط الدعوى الجمركية عند اجراء المصالحة عليها.","title":"التسوية الصلحية في القضايا الجمركية","memo":"⭐ للرئيس أو المفوض المختص، لأسباب مبررة، عقد تسوية صلحية قبل إقامة الدعوى أو خلالها وقبل صدور الحكم البدائي\n⭐ لا يجوز أن تتم التسوية بأقل من نصف الحد الأدنى المنصوص عليه\n⭐ يصدر الرئيس دليلاً بالتسويات يُنشر في الجريدة الرسمية، وتسقط الدعوى الجمركية بالمصالحة","qs":[{"q":"يجوز عقد التسوية الصلحية في القضايا الجمركية في المنطقة:","o":["قبل إقامة الدعوى أو خلال النظر فيها وقبل صدور الحكم البدائي","بعد صدور الحكم القطعي فقط","قبل إقامة الدعوى حصراً","في أي وقت حتى بعد تنفيذ الحكم"],"a":0},{"q":"الحد الأدنى الذي لا يجوز أن تتم التسوية الصلحية في القضايا الجمركية بأقل منه:","o":["نصف الحد الأدنى المنصوص عليه في القانون","الحد الأدنى المنصوص عليه كاملاً","ربع الحد الأدنى","نصف الحد الأعلى"],"a":0},{"q":"الأثر المترتب على إجراء المصالحة في الدعوى الجمركية:","o":["سقوط الدعوى الجمركية","تخفيض العقوبة إلى النصف","وقف تنفيذ الحكم مدة سنة","إحالة الدعوى إلى محكمة الجمارك الاستئنافية"],"a":0}]},{"n":"55","chapter":"","notes":[],"source":"لا تطبق في المنطقة أحكام قانون الاستيراد والتصدير وأحكام الحوافز والقيود على راس المال الاجنبي المنصوص عليها في قانون تشجيع الاستثمار والانظمة الصادرة بمقتضاه.","title":"قوانين لا تطبق في المنطقة","memo":"⭐ لا يطبق في المنطقة قانون الاستيراد والتصدير\n⭐ ولا أحكام الحوافز والقيود على رأس المال الأجنبي في قانون تشجيع الاستثمار","qs":[{"q":"أي من التشريعات التالية لا تطبق أحكامه في المنطقة وفق قانون المنطقة؟","o":["قانون الاستيراد والتصدير","قانون البنوك","قانون مراقبة أعمال التأمين","قانون ضريبة الدخل"],"a":0},{"q":"من قانون تشجيع الاستثمار لا تطبق في المنطقة الأحكام المتعلقة بـ:","o":["الحوافز والقيود على رأس المال الأجنبي","تسجيل الشركات","الإعفاءات الجمركية للأفراد","المناطق التنموية"],"a":0}]},{"n":"56","chapter":"","notes":[],"source":"يصدر مجلس الوزراء الانظمة اللازمة لتنفيذ أحكام هذا القانون بما في ذلك ما يتعلق منها بما يلي:\nأ-تحديد الرسوم التي تفرض لمصلحة السلطة وفقا لأحكام هذا القانون\nب-شؤون الموظفين والمستخدمين في السلطة.\nج-شؤون اللوازم والاشغال والامور المالية في السلطة.\nد-تاليف شرطة ساحلية في المنطقة وتنظيم عملها وتحديد صلاحياتها.\nه-تنظيم وادارة متنزه العقبة البحري.","title":"الأنظمة التنفيذية للقانون","memo":"⭐ يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ القانون\n⭐ منها: رسوم السلطة، شؤون الموظفين، اللوازم والأشغال والأمور المالية، تأليف شرطة ساحلية، تنظيم وإدارة متنزه العقبة البحري","qs":[{"q":"الجهة التي تصدر الأنظمة اللازمة لتنفيذ قانون منطقة العقبة الاقتصادية الخاصة:","o":["مجلس الوزراء","المجلس","الرئيس","مجلس الأمة"],"a":0},{"q":"أي مما يلي لا يرد ضمن الأمور التي تصدر بها أنظمة وفق المادة الخاصة بالأنظمة التنفيذية؟","o":["تعيين رئيس محكمة بداية العقبة","تأليف شرطة ساحلية في المنطقة","تنظيم وإدارة متنزه العقبة البحري","شؤون اللوازم والأشغال في السلطة"],"a":0}]},{"n":"57","chapter":"","notes":[],"source":"يلغى ( قانون سلطة اقليم العقبة) رقم (7) لسنة 1987 والتعديلات التي طرأت عليه اعتبارا من التاريخ الذي يحدده مجلس الوزراء وفق أحكام المادة (8) من هذا القانون على ان يستمر العمل بالانظمة والتعليمات الصادرة بمقتضاه إلى ان تلغى او يستبدل غيرها بها وفقا لأحكام هذا القانون.","title":"إلغاء قانون سلطة إقليم العقبة","memo":"⭐ يلغى قانون سلطة إقليم العقبة رقم (7) لسنة 1987 من التاريخ الذي يحدده مجلس الوزراء وفق المادة (8)\n⭐ يستمر العمل بالأنظمة والتعليمات الصادرة بمقتضاه إلى أن تلغى أو يستبدل غيرها بها","qs":[{"q":"القانون الذي ألغاه قانون منطقة العقبة الاقتصادية الخاصة:","o":["قانون سلطة إقليم العقبة رقم (7) لسنة 1987","قانون المناطق الحرة رقم (32) لسنة 1984","قانون تشجيع الاستثمار رقم (16) لسنة 1995","قانون المناطق التنموية لسنة 2008"],"a":0},{"q":"مصير الأنظمة والتعليمات الصادرة بمقتضى القانون الملغى:","o":["يستمر العمل بها إلى أن تلغى أو يستبدل غيرها بها","تلغى حكماً من تاريخ نفاذ القانون الجديد","يستمر العمل بها مدة سنة واحدة فقط","تحتاج إلى مصادقة مجلس الأمة لاستمرارها"],"a":0}]},{"n":"58","chapter":"","notes":[],"source":"رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون .","title":"تنفيذ القانون","memo":"⭐ رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون","qs":[]}]};
